const safeUrl=u=>{if(!u)return'#';try{const v=/^https?:\/\//i.test(String(u))?String(u):'https://'+String(u);const x=new URL(v);return ['http:','https:'].includes(x.protocol)?x.href:'#'}catch{return'#'}};const safeMediaUrl=u=>/^data:image\/(png|jpeg|jpg|gif|webp|svg\+xml);base64,/i.test(String(u||''))?String(u):safeUrl(u);
