function routeFromHash(){let raw='home';try{raw=decodeURIComponent((location.hash||'#home').slice(1))}catch{history.replaceState(null,'','#home');return'home'}return validRoute(raw)?raw:'home'}
function go(view,replace=false){if(!validRoute(view))view='home';const next='#'+encodeURIComponent(view).replace(/%3A/g,':');if(location.hash===next){S.view=view;render();window.scrollTo({top:0,behavior:'smooth'});return}if(replace)history.replaceState(null,'',next);else location.hash=next}
let toastTimer,lastToastMessage='',lastToastAt=0;function toast(message,type=''){const host=$('#toastHost');if(!host)return;const msg=String(message||''),now=Date.now();if(msg===lastToastMessage&&now-lastToastAt<5000)return;lastToastMessage=msg;lastToastAt=now;host.replaceChildren();const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;host.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>{host.replaceChildren();if(lastToastMessage===msg)lastToastMessage=''},4200)}
function setNetworkBadge(){const el=$('#netBadge');if(!el)return;S.online=navigator.onLine;el.hidden=S.online;if(!S.online)el.textContent='Sin conexión · algunas funciones no estarán disponibles'}
function friendlyError(e,fallback='Ocurrió un error inesperado.'){const m=String(e?.message||'');if(e?.name==='AbortError'||/aborted|timeout/i.test(m))return'La conexión tardó demasiado. Intenta nuevamente.';if(/Failed to fetch|NetworkError/i.test(m))return'No se pudo conectar con el servidor.';return m||fallback}

function req(path,opt={}){const c=new AbortController(),t=setTimeout(()=>c.abort(),7000);const h={'apikey':KEY,'Content-Type':'application/json',...(S.token?{'Authorization':'Bearer '+S.token}:{}),...(opt.headers||{})};return fetch(URL+path,{...opt,headers:h,signal:c.signal}).finally(()=>clearTimeout(t))}
async function jreq(path,opt={}){const r=await req(path,opt);if(!r.ok)throw new Error((await r.text()).slice(0,220)||r.statusText);const tx=await r.text();return tx?JSON.parse(tx):null}
async function storageUpload(file,path,upsert=true){
 if(!S.token)throw new Error('Debes iniciar sesión para subir archivos.');
 if(!file||!/^image\/(jpeg|png|webp|gif)$/i.test(file.type||''))throw new Error('Usa una imagen JPG, PNG, WEBP o GIF.');
 if(file.size>8388608)throw new Error('La imagen supera el límite de 8 MB.');
 const clean=path.split('/').map(x=>encodeURIComponent(x)).join('/');
 const r=await fetch(`${URL}/storage/v1/object/nlobi-media/${clean}`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':file.type,'x-upsert':upsert?'true':'false','cache-control':'3600'},body:file});
 if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo subir la imagen.');
 return storagePublicUrl(path)
}
function storagePublicUrl(path){return `${URL}/storage/v1/object/public/nlobi-media/${path.split('/').map(x=>encodeURIComponent(x)).join('/')}`}
function storageExt(file){const m={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'};return m[file?.type]||'img'}
function storageName(prefix,file){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}.${storageExt(file)}`}

async function storageListFolder(prefix){
 const r=await fetch(`${URL}/storage/v1/object/list/nlobi-media`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':'application/json'},body:JSON.stringify({prefix,limit:1000,offset:0,sortBy:{column:'updated_at',order:'desc'}})});
 if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo listar Storage.');
 return await r.json()
}
async function storageWalk(prefix,depth=0){
 if(depth>8)return[];
 const rows=await storageListFolder(prefix),out=[];
 for(const x of rows||[]){
  const path=prefix?`${prefix}/${x.name}`:x.name;
  const isFolder=!x.id&&(!x.metadata||Object.keys(x.metadata||{}).length===0);
  if(isFolder)out.push(...await storageWalk(path,depth+1));
  else if(/\.(jpe?g|png|webp|gif)$/i.test(x.name||''))out.push({name:x.name,path,size:x.metadata?.size||0,mimetype:x.metadata?.mimetype||'',updated_at:x.updated_at||x.created_at||''})
 }
 return out
}
async function storageDelete(path){
 const r=await fetch(`${URL}/storage/v1/object/nlobi-media`,{method:'DELETE',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':'application/json'},body:JSON.stringify({prefixes:[path]})});
 if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo eliminar el archivo.');
 return true
}
function dataUrlToBlob(dataUrl){
 const m=String(dataUrl||'').match(/^data:(image\/(?:png|jpeg|jpg|webp|gif));base64,(.+)$/i);if(!m)return null;
 const bin=atob(m[2]),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 return new Blob([bytes],{type:m[1].replace('jpg','jpeg')})
}
async function materializeImportedImages(blocks,groupId,sectionKey){
 const out=[];let n=0;
 for(const raw of blocks||[]){
  const b=normalizeImportBlock(raw);
  if(b.type==='image'&&/^data:image\//i.test(b.url||'')){
   const blob=dataUrlToBlob(b.url);
   if(blob){n++;const file=new File([blob],`import-${n}.${storageExt(blob)}`,{type:blob.type});const path=`teams/${groupId}/imports/${sectionKey}/${storageName('image',file)}`;b.url=await storageUpload(file,path,false)}
  }
  out.push(b)
 }
 return out
}

function nav(){
 const unread=S.notes.filter(x=>!x.read_at).length;
 const active=v=>S.view===v||S.view.startsWith(v+':')?'active':'';
 return `<header class="top"><div class="bar"><div class="brand"><span class="brandMark">N</span>NLOBI</div><nav class="nav">
 <button class="${active('home')}" data-v="home">Inicio</button><button class="${active('explore')}" data-v="explore">Explorar</button><button class="${active('library')}" data-v="library">Biblioteca</button>
 ${S.user?`<button class="${active('notifications')}" data-v="notifications">Avisos${unread?` · ${unread}`:''}</button><button class="${active('beta')}" data-v="beta">Beta</button>`:''}
 ${S.groups.length?`<button class="${active('studio')}" data-v="studio">Studio</button>`:''}${S.admin?`<button class="${active('admin')}" data-v="admin">Admin</button>`:''}
 <button class="${active('auth')}" data-v="auth">${S.user?'Perfil':'Entrar'}</button>${S.pwaInstallReady?'<button id="installPwa" class="installHint" title="Instalar NLOBI">＋ Instalar</button>':''}<button id="theme" aria-label="Cambiar tema" title="Cambiar tema">◐</button></nav></div></header>${!S.online?'<div class="offlinePill">Sin conexión · modo lectura offline</div>':''}` }
function status(){return S.err?`<div class="status bad" role="alert"><strong>Hay un problema de conexión.</strong><div>${esc(S.err)}</div><div style="margin-top:8px"><button class="btn" id="retryBackend">Reintentar</button></div></div>`:''}
function coverMarkup(x,detail=false){
 const img=coverOf(x), t=esc(titleOf(x));
 return `<div class="${detail?'detailCover':'cover'}">${img?`<img src="${esc(safeMediaUrl(img))}" alt="Portada de ${t}" loading="lazy" decoding="async">`:''}${x.demo?'<span class="demoRibbon">Vista previa</span>':''}<span class="${detail?'':'coverTitle'}">${t}</span></div>`
}
function visibleCatalog(){return S.catalog.length?S.catalog:demo}
function card(x){
 return `<article class="novelCard">${coverMarkup(x)}<div class="cardBody"><div class="metaRow"><span class="badge">${esc((x.language_code||'es').toUpperCase())}</span><span class="badge">${x.demo?'Demo':'Publicada'}</span></div><h3>${esc(titleOf(x))}</h3><div class="muted">${esc(x.translator_groups?.name||'Equipo traductor')}</div><div class="cardActions"><button class="btn primary" data-open="${x.id}">Ver obra</button>${S.user&&!x.demo?`<button class="btn" data-lib="${x.id}">+ Biblioteca</button>`:''}</div></div></article>`
}
function catalogGrid(){return `<div class="novelGrid">${visibleCatalog().map(card).join('')}</div>`}
function home(){
 const real=S.catalog.length;
 return `${nav()}<main class="wrap">${status()}
 <section class="hero"><div class="heroCopy"><span class="eyebrow">Biblioteca digital · lectores y traductores</span><h1>Tu próxima novela ligera empieza aquí.</h1><p>Descubre traducciones, sigue equipos, guarda tu progreso y continúa leyendo desde cualquier dispositivo.</p><div class="heroActions"><button class="btn" data-v="explore">Explorar catálogo</button><button class="btn secondary" data-v="${S.user?'library':'auth'}">${S.user?'Abrir mi biblioteca':'Crear cuenta'}</button></div></div><div class="heroShelf"><div class="miniBook">Fantasía</div><div class="miniBook">Romance</div><div class="miniBook">Aventura</div></div></section>
 <div class="kpis"><div class="kpi"><b>${real}</b><span>traducciones públicas</span></div><div class="kpi"><b>${S.library.length}</b><span>en tu biblioteca</span></div><div class="kpi"><b>${S.groups.length}</b><span>equipos vinculados</span></div><div class="kpi"><b>${S.notes.filter(n=>!n.read_at).length}</b><span>avisos pendientes</span></div></div>
 <div class="sectionHead"><div><h2>${real?'Últimas publicaciones':'Así se verá tu catálogo'}</h2><p>${real?'Contenido publicado por equipos aprobados.':'Vista previa visual mientras llegan las primeras publicaciones reales.'}</p></div><button class="btn ghost" data-v="explore">Ver todo →</button></div>${catalogGrid()}
 </main>`
}
function catalogGenres(){return [...new Set(visibleCatalog().flatMap(x=>x.novels?.genres||[]).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function catalogTags(){return [...new Set(visibleCatalog().flatMap(x=>x.novels?.tags||[]).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function filteredCatalog(){const q=S.searchQuery.trim().toLowerCase();let arr=visibleCatalog().filter(x=>{const title=titleOf(x).toLowerCase(),group=(x.translator_groups?.name||'').toLowerCase(),author=(x.novels?.author_name||'').toLowerCase(),lang=(x.language_code||'es').toLowerCase(),st=(x.status||'active').toLowerCase(),genres=(x.novels?.genres||[]),tags=(x.novels?.tags||[]);return(!q||title.includes(q)||group.includes(q)||author.includes(q)||genres.some(g=>g.toLowerCase().includes(q))||tags.some(t=>t.toLowerCase().includes(q)))&&(S.searchStatus==='all'||st===S.searchStatus)&&(S.searchLanguage==='all'||lang===S.searchLanguage)&&(S.searchGenre==='all'||genres.includes(S.searchGenre))&&(S.searchTag==='all'||tags.includes(S.searchTag))});if(S.searchSort==='popular')arr.sort((a,b)=>Number(b.popularity_score||0)-Number(a.popularity_score||0)||new Date(b.updated_at||0)-new Date(a.updated_at||0));else if(S.searchSort==='title')arr.sort((a,b)=>titleOf(a).localeCompare(titleOf(b)));else if(S.searchSort==='complete')arr.sort((a,b)=>(b.status==='complete')-(a.status==='complete')||new Date(b.updated_at||0)-new Date(a.updated_at||0));else arr.sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0));return arr}
function explore(){const langs=[...new Set(visibleCatalog().map(x=>(x.language_code||'es').toLowerCase()))],genres=catalogGenres(),tags=catalogTags(),results=filteredCatalog();return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Explorar</span><h2>Encuentra tu próxima lectura</h2><p>Busca por título, autor, equipo, género o etiqueta.</p></div></div><div class="filterGrid"><input id="catalogSearch" value="${esc(S.searchQuery)}" placeholder="Buscar novela, autor, género..."><select id="catalogStatus"><option value="all">Todos los estados</option><option value="active" ${S.searchStatus==='active'?'selected':''}>Activa</option><option value="complete" ${S.searchStatus==='complete'?'selected':''}>Completa</option><option value="paused" ${S.searchStatus==='paused'?'selected':''}>Pausada</option></select><select id="catalogLanguage"><option value="all">Todos los idiomas</option>${langs.map(l=>`<option value="${esc(l)}" ${S.searchLanguage===l?'selected':''}>${esc(l.toUpperCase())}</option>`).join('')}</select><select id="catalogGenre"><option value="all">Todos los géneros</option>${genres.map(g=>`<option value="${esc(g)}" ${S.searchGenre===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="catalogSort"><option value="updated" ${S.searchSort==='updated'?'selected':''}>Actualizadas</option><option value="popular" ${S.searchSort==='popular'?'selected':''}>Popularidad</option><option value="title" ${S.searchSort==='title'?'selected':''}>Título</option><option value="complete" ${S.searchSort==='complete'?'selected':''}>Completas primero</option></select></div>${tags.length?`<div class="chipRow"><button class="chip ${S.searchTag==='all'?'active':''}" data-tag-filter="all">Todas</button>${tags.slice(0,24).map(t=>`<button class="chip ${S.searchTag===t?'active':''}" data-tag-filter="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<div class="row" style="justify-content:space-between;margin:10px 0 16px"><span class="muted">${results.length} resultados</span><button class="btn" id="clearCatalogFilters">Limpiar filtros</button></div>${results.length?`<div class="novelGrid">${results.map(card).join('')}</div>`:`<div class="empty"><div class="emptyArt">⌕</div><strong>No encontramos resultados</strong><div>Prueba con otros filtros o palabras.</div></div>`}</main>`}
function collectionData(slug){const all=visibleCatalog().slice();if(slug==='popular')return{title:'Más populares',desc:'Traducciones con mayor actividad agregada en NLOBI.',items:all.sort((a,b)=>Number(b.popularity_score||0)-Number(a.popularity_score||0)).slice(0,30)};if(slug==='recent')return{title:'Actualizadas recientemente',desc:'Proyectos con cambios más recientes.',items:all.sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0)).slice(0,30)};if(slug==='complete')return{title:'Completas',desc:'Traducciones marcadas como completas.',items:all.filter(x=>x.status==='complete').sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0))};if(slug.startsWith('genre-')){const g=decodeURIComponent(slug.slice(6));return{title:g,desc:`Obras del género ${g}.`,items:all.filter(x=>(x.novels?.genres||[]).includes(g))}}return{title:'Colección',desc:'Selección de NLOBI.',items:all}}
function collectionView(){const slug=S.view.split(':').slice(1).join(':'),C=collectionData(slug);return `${nav()}<main class="wrap">${status()}<div class="collectionHero"><span class="eyebrow" style="color:var(--accent)">Colección</span><h1>${esc(C.title)}</h1><p>${esc(C.desc)}</p><button class="btn" data-v="explore">Explorar todo</button></div>${C.items.length?`<div class="novelGrid">${C.items.map(card).join('')}</div>`:'<div class="empty">Todavía no hay títulos en esta colección.</div>'}</main>`}
function libraryProgressFor(id){return S.readingProgress.find(x=>x.translation_id===id)||null}
function cachedChapterIndex(){try{return JSON.parse(localStorage.getItem('nlobi_cached_chapters')||'[]')}catch{return[]}}
function libraryFiltered(){if(S.libraryFilter==='all')return S.library;if(S.libraryFilter==='favorites')return S.library.filter(x=>x.is_favorite);return S.library.filter(x=>x.status===S.libraryFilter)}
function library(){
 if(!S.user)return `${nav()}<main class="wrap"><div class="authShell"><div class="authVisual"><h2>Tu biblioteca, siempre contigo.</h2><p>Guarda lecturas, continúa donde te quedaste y sincroniza tu progreso.</p></div><div class="authPanel"><h1>Biblioteca personal</h1><p class="muted">Inicia sesión para ver tus novelas guardadas.</p><button class="btn primary" data-v="auth">Iniciar sesión</button></div></div></main>`;
 const filtered=libraryFiltered(),reading=S.library.filter(x=>x.status==='reading').length,planned=S.library.filter(x=>x.status==='plan_to_read').length,completed=S.library.filter(x=>x.status==='completed').length,favorites=S.library.filter(x=>x.is_favorite).length,cached=cachedChapterIndex();
 return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><h2>Mi biblioteca</h2><p>${S.library.length?`${S.library.length} títulos guardados.`:'Empieza guardando una novela desde Explorar.'}</p></div><button class="btn" data-v="explore">+ Añadir lecturas</button></div>
 <div class="libraryDashboard"><div class="libraryStat"><b>${reading}</b><span>Leyendo</span></div><div class="libraryStat"><b>${planned}</b><span>Por leer</span></div><div class="libraryStat"><b>${completed}</b><span>Completadas</span></div><div class="libraryStat"><b>${favorites}</b><span>Favoritas</span></div><div class="libraryStat"><b>${cached.length}</b><span>Offline</span></div></div>
 ${S.readingProgress.length?`<div class="sectionHead"><div><h2>Continuar leyendo</h2><p>Retoma exactamente la última obra sincronizada.</p></div></div><div class="novelGrid">${S.readingProgress.slice().sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0)).slice(0,4).map(p=>{const lib=S.library.find(x=>x.translation_id===p.translation_id),t=lib?.translations;return `<article class="novelCard"><div class="cardBody"><span class="badge">${Math.round(Number(p.progress_percent||0))}%</span><h3>${esc(t?.novels?.title||t?.title||'Lectura')}</h3><div class="muted">${esc(p.sections?.title||'Último capítulo')} · Vol. ${esc(p.volumes?.volume_number||'')}</div><div class="libraryProgress"><span style="width:${Math.max(0,Math.min(100,Number(p.progress_percent||0)))}%"></span></div>${p.section_id?`<button class="btn primary" data-continue-section="${p.section_id}" data-translation="${p.translation_id}">Continuar</button>`:''}</div></article>`}).join('')}</div>`:''}
 <div class="sectionHead"><div><h2>Mis lecturas</h2></div></div><div class="libraryFilters">${[['all','Todas'],['reading','Leyendo'],['plan_to_read','Por leer'],['completed','Completadas'],['paused','Pausadas'],['dropped','Abandonadas'],['favorites','Favoritas']].map(([k,l])=>`<button class="chip ${S.libraryFilter===k?'active':''}" data-library-filter="${k}">${l}</button>`).join('')}</div>
 <div class="libraryList">${filtered.length?filtered.map(x=>{const t=x.translations,p=libraryProgressFor(x.translation_id);return `<div class="libraryCard ${x.is_favorite?'isFavorite':''}"><div class="libraryThumb">${t?.novels?.cover_url?`<img src="${esc(safeMediaUrl(t.novels.cover_url))}" alt="Portada de ${esc(t?.novels?.title||t?.title||'Novela')}" loading="lazy" decoding="async">`:''}</div><div class="libraryMeta"><div class="row"><span class="statusPill">${esc(statusLabel(x.status))}</span>${x.is_favorite?'<span class="badge">★ Favorita</span>':''}</div><h3>${esc(t?.novels?.title||t?.title||'Novela')}</h3><div class="muted">${esc(t?.translator_groups?.name||'Traducción guardada')}</div>${p?`<div class="libraryProgress"><span style="width:${Math.max(0,Math.min(100,Number(p.progress_percent||0)))}%"></span></div><div class="muted">${Math.round(Number(p.progress_percent||0))}% · ${esc(p.sections?.title||'Progreso guardado')}</div>`:''}</div><div class="libraryActions"><select data-library-status="${x.translation_id}"><option value="plan_to_read" ${x.status==='plan_to_read'?'selected':''}>Por leer</option><option value="reading" ${x.status==='reading'?'selected':''}>Leyendo</option><option value="completed" ${x.status==='completed'?'selected':''}>Completada</option><option value="paused" ${x.status==='paused'?'selected':''}>Pausada</option><option value="dropped" ${x.status==='dropped'?'selected':''}>Abandonada</option></select><button class="btn" data-library-favorite="${x.translation_id}">${x.is_favorite?'★':'☆'} Favorito</button>${p?.section_id?`<button class="btn primary" data-continue-section="${p.section_id}" data-translation="${x.translation_id}">Continuar</button>`:`<button class="btn primary" data-open="${x.translation_id}">Abrir</button>`}<button class="btn danger" data-library-remove="${x.translation_id}">Quitar</button></div></div>`}).join(''):`<div class="empty"><div class="emptyArt">📚</div><strong>No hay títulos en esta vista</strong><div>Cambia el filtro o añade una lectura.</div></div>`}</div>
 <div class="sectionHead"><div><h2>Historial reciente</h2><p>Privado: solo tú puedes consultar los capítulos abiertos recientemente.</p></div>${S.readingHistory.length?'<button class="btn" id="clearReadingHistory">Limpiar historial</button>':''}</div><div class="historyGrid">${S.readingHistory.length?S.readingHistory.slice(0,20).map(h=>`<div class="historyRow"><div><strong>${esc(h.sections?.volumes?.translations?.novels?.title||'Obra')}</strong><div>${esc(h.sections?.title||'Capítulo')}</div><div class="muted">${esc((h.viewed_at||'').replace('T',' ').slice(0,16))}</div></div><button class="btn" data-continue-section="${h.section_id}" data-translation="${h.translation_id}">Abrir</button></div>`).join(''):'<div class="empty">Todavía no hay historial de lectura.</div>'}</div>
 <div class="sectionHead"><div><h2>Disponible sin conexión</h2><p>Capítulos guardados en este dispositivo.</p></div>${cached.length?'<button class="btn danger" id="clearOfflineLibrary">Eliminar todos</button>':''}</div><div class="offlineList">${cached.length?cached.map(c=>`<div class="offlineRow"><div><strong>${esc(c.novel_title||'Obra')}</strong><div>${esc(c.title||'Capítulo')}</div><div class="muted">Guardado ${esc((c.cached_at||'').replace('T',' ').slice(0,16))}</div></div><div class="row"><button class="btn" data-offline-open="${c.id}">Leer offline</button><button class="btn danger" data-offline-remove="${c.id}">Eliminar</button></div></div>`).join(''):'<div class="empty">Abre un capítulo una vez para que pueda quedar disponible offline.</div>'}</div>
 </main>`
}
function auth(){
 if(S.user)return `${nav()}<main class="wrap">${status()}<div class="profileHero"><div class="profileAvatar">${S.profile?.avatar_url?`<img src="${esc(safeUrl(S.profile.avatar_url))}" alt="${esc(S.profile?.display_name||'Perfil')}">`:esc((S.profile?.display_name||'U').slice(0,1))}</div><div><span class="badge">${esc(S.profile?.account_type||'reader')}</span><h1 style="font-family:Georgia,serif;margin:8px 0">${esc(S.profile?.display_name||S.user.email||'Cuenta')}</h1>${S.profile?.username?`<div class="muted">@${esc(S.profile.username)}</div>`:''}<p>${esc(S.profile?.bio||'Sin biografía todavía.')}</p><div class="row"><button class="btn" data-profile="${S.user.id}">Ver perfil público</button>${!S.groups.length&&['translator','reader_translator'].includes(S.profile?.account_type)?'<button class="btn primary" data-v="application">Solicitar equipo traductor</button>':''}</div></div></div><div class="sectionHead"><div><h2>Editar perfil</h2><p>Estos datos pertenecen a tu identidad personal y no muestran afiliaciones de traducción.</p></div></div><div class="authShell"><div class="authVisual"><h2>Tu espacio personal</h2><p>Controla qué lectura quieres compartir públicamente.</p></div><div class="authPanel"><div class="field"><label>Nombre visible</label><input id="profileDisplayName" value="${esc(S.profile?.display_name||'')}"></div><div class="field"><label>Nombre de usuario</label><input id="profileUsername" value="${esc(S.profile?.username||'')}" placeholder="usuario"></div><div class="field"><label>Avatar</label><input id="profileAvatarUrl" value="${esc(S.profile?.avatar_url||'')}" placeholder="https://..."><div class="mediaPicker"><input id="profileAvatarFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="uploadHint">Subir a NLOBI · máximo 8 MB.</div></div></div><div class="field"><label>Biografía</label><textarea id="profileBio" rows="5">${esc(S.profile?.bio||'')}</textarea></div><label class="radio"><input type="checkbox" id="profilePublicLibrary" ${S.profile?.public_library?'checked':''}><span><b>Biblioteca pública</b><br><span class="muted">Permite mostrar tus lecturas guardadas en tu perfil público.</span></span></label><label class="radio"><input type="checkbox" id="profilePublicActivity" ${S.profile?.public_activity?'checked':''}><span><b>Actividad de lectura pública</b><br><span class="muted">Permite mostrar progreso reciente de lectura.</span></span></label><div class="row"><button class="btn primary" id="savePersonalProfile">Guardar perfil</button><button class="btn" id="logout">Cerrar sesión</button></div></div></div></main>`;
 return `${nav()}<main class="wrap">${status()}<div class="authShell"><div class="authVisual"><span class="eyebrow">Cuenta NLOBI</span><h2>Una biblioteca que recuerda dónde te quedaste.</h2><p>Para lectores, traductores y equipos que quieren publicar de forma ordenada.</p></div><div class="authPanel"><div class="switch"><button id="loginTab" class="${S.authMode==='login'?'active':''}">Iniciar sesión</button><button id="signupTab" class="${S.authMode==='signup'?'active':''}">Crear cuenta</button></div>${S.authMode==='login'?`<h1>Bienvenido de nuevo</h1><div class="field"><label>Correo</label><input id="email" type="email" autocomplete="email"></div><div class="field"><label>Contraseña</label><input id="pass" type="password" autocomplete="current-password"></div><button class="btn primary" id="login">Entrar</button>`:`<h1>Crea tu cuenta</h1><div class="field"><label>Nombre visible</label><input id="name"></div><div class="field"><label>Correo</label><input id="email" type="email"></div><div class="field"><label>Contraseña</label><input id="pass" type="password"></div><label class="radio"><input type="radio" name="atype" value="reader" checked><span><b>Solo lector</b><br><span class="muted">Biblioteca, seguimiento y lectura.</span></span></label><label class="radio"><input type="radio" name="atype" value="reader_translator"><span><b>Lector y traductor</b><br><span class="muted">Lee y solicita acceso a Studio.</span></span></label><label class="radio"><input type="radio" name="atype" value="translator"><span><b>Solo traductor</b><br><span class="muted">Cuenta enfocada en publicación.</span></span></label><button class="btn primary" id="signup">Crear cuenta</button>`}</div></div></main>`
}
function application(){return `${nav()}<main class="wrap">${status()}<div class="authShell"><div class="authVisual"><h2>Publica con tu equipo.</h2><p>Las solicitudes se revisan antes de habilitar Studio.</p></div><div class="authPanel"><h1>Alta de equipo traductor</h1><div class="field"><label>Nombre del equipo</label><input id="teamName"></div><div class="field"><label>Descripción</label><textarea id="teamDesc" rows="5"></textarea></div><div class="field"><label>Sitio web</label><input id="teamWeb" placeholder="https://..."></div><button class="btn primary" id="sendApp">Enviar solicitud</button></div></div></main>`}
function studio(){
 if(!S.groups.length)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">✦</div><strong>Studio todavía no está habilitado</strong><div>Necesitas pertenecer a un equipo traductor aprobado.</div></div></main>`;
 if(S.view==='studio:import')return studioImport();
 if(S.view==='studio:new')return studioNewProject();
 if(S.view.startsWith('studio:media:'))return studioMediaView();
 if(S.view.startsWith('studio:team:'))return studioTeamView();
 if(S.view.startsWith('studio:project:'))return studioProjectView();
 return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><h2>Studio</h2><p>Proyectos, publicación e importación de tu equipo.</p></div><div class="row"><button class="btn" data-v="studio:import">Importar archivo</button><button class="btn primary" data-v="studio:new">+ Nuevo proyecto</button></div></div>
 <div class="studioList">${S.studioTranslations.length?S.studioTranslations.map(t=>`<div class="projectRow"><div><div class="row"><span class="badge">${esc(t.status||'active')}</span><span class="badge">${esc((t.language_code||'es').toUpperCase())}</span></div><h3>${esc(t.novels?.title||t.title||'Proyecto')}</h3><div class="muted">${esc(t.translator_groups?.name||'Equipo')}</div></div><button class="btn primary" data-studio-project="${t.id}">Gestionar</button></div>`).join(''):`<div class="empty"><div class="emptyArt">✎</div><strong>Aún no tienes proyectos</strong><div>Crea la primera obra de tu equipo o importa un archivo.</div><div style="margin-top:12px"><button class="btn primary" data-v="studio:new">Crear proyecto</button></div></div>`}</div></main>`
}


function mediaFiltered(){const q=S.mediaQuery.trim().toLowerCase();return (S.mediaFiles||[]).filter(x=>!q||x.name.toLowerCase().includes(q)||x.path.toLowerCase().includes(q))}
function formatBytes(n){n=Number(n||0);if(!n)return'—';if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}
function studioMediaView(){const gid=S.mediaGroupId||S.view.split(':')[2],files=mediaFiltered();return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Multimedia</span><h2>Biblioteca multimedia</h2><p>Reutiliza portadas, banners e ilustraciones ya almacenadas por el equipo.</p></div><button class="btn" id="mediaBack">← Volver</button></div><div class="mediaStats"><span class="badge">${S.mediaFiles.length} archivos</span><span class="badge">${formatBytes(S.mediaFiles.reduce((n,x)=>n+Number(x.size||0),0))}</span>${S.mediaTarget?`<span class="badge">Seleccionando para: ${esc(mediaTargetLabel(S.mediaTarget))}</span>`:''}</div><div class="mediaToolbar"><input id="mediaSearch" value="${esc(S.mediaQuery)}" placeholder="Buscar por nombre o carpeta..."><label class="btn primary">+ Subir imagen<input id="mediaUploadFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden></label></div>${S.mediaLoading?'<div class="empty">Cargando archivos…</div>':files.length?`<div class="mediaGrid">${files.map(f=>`<article class="mediaCard"><div class="mediaThumb"><img src="${esc(storagePublicUrl(f.path))}" alt="${esc(f.name)}" loading="lazy"></div><div class="mediaBody"><div class="mediaName" title="${esc(f.name)}">${esc(f.name)}</div><div class="mediaPath">${esc(f.path)}</div><div class="muted">${formatBytes(f.size)}${f.updated_at?` · ${esc(String(f.updated_at).slice(0,10))}`:''}</div><div class="mediaActions">${S.mediaTarget?`<button class="btn primary" data-media-use="${esc(f.path)}">Usar aquí</button>`:''}<button class="btn" data-media-copy="${esc(f.path)}">Copiar URL</button><button class="btn danger" data-media-delete="${esc(f.path)}">Eliminar</button></div></div></article>`).join('')}</div>`:'<div class="empty"><div class="emptyArt">▧</div><strong>No hay imágenes</strong><div>Sube la primera imagen o cambia la búsqueda.</div></div>'}</main>`}
function mediaTargetLabel(t){if(t==='team-avatar')return'avatar del equipo';if(t==='team-banner')return'banner del equipo';if(t==='novel-cover')return'portada de la obra';if(t.startsWith('volume-cover:'))return'portada de volumen';if(t.startsWith('block:'))return'ilustración';return'uso general'}
function studioTeamView(){const G=S.studioTeam;if(!G)return `${nav()}<main class="wrap"><div class="empty">Cargando equipo…</div></main>`;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Equipo</span><h2>${esc(G.name)}</h2><p>Identidad pública y enlaces de apoyo del equipo.</p></div><div class="row"><button class="btn" data-media-open="${G.id}" data-target="">Biblioteca multimedia</button><button class="btn" data-v="studio">← Studio</button></div></div>
 <div class="authShell"><div class="authVisual" ${G.banner_url?`style="background-image:linear-gradient(145deg,rgba(40,24,16,.68),rgba(110,70,45,.68)),url('${esc(safeUrl(G.banner_url))}');background-size:cover;background-position:center"`:''}><h2>${esc(G.name)}</h2><p>${esc(G.description||'Configura cómo se presenta tu equipo públicamente.')}</p></div><div class="authPanel"><div class="field"><label>Nombre</label><input id="teamEditName" value="${esc(G.name||'')}"></div><div class="field"><label>Descripción</label><textarea id="teamEditDescription" rows="5">${esc(G.description||'')}</textarea></div><div class="field"><label>Avatar</label><input id="teamEditAvatar" value="${esc(G.avatar_url||'')}" placeholder="https://..."><div class="mediaPicker"><input id="teamAvatarFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="uploadHint">Subir al almacenamiento de NLOBI.</div><button class="btn" type="button" data-media-open="${G.id}" data-target="team-avatar">Elegir existente</button></div></div><div class="field"><label>Banner</label><input id="teamEditBanner" value="${esc(G.banner_url||'')}" placeholder="https://..."><div class="mediaPicker"><input id="teamBannerFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="uploadHint">Subir al almacenamiento de NLOBI.</div><button class="btn" type="button" data-media-open="${G.id}" data-target="team-banner">Elegir existente</button></div></div><div class="row"><div class="field" style="flex:1"><label>Color principal</label><input id="teamEditPrimary" value="${esc(G.primary_color||'')}"></div><div class="field" style="flex:1"><label>Color secundario</label><input id="teamEditSecondary" value="${esc(G.secondary_color||'')}"></div></div><button class="btn primary" id="saveTeamProfile">Guardar perfil</button></div></div>
 <div class="sectionHead"><div><h2>Miembros y roles</h2><p>Owner y admin administran accesos. Translator/editor pueden trabajar contenido sin gestionar miembros.</p></div></div>
 <div class="panelGrid"><div class="panelCard"><h3>Agregar miembro</h3>${isCurrentGroupManager(G.id)?`<div class="field"><label>Nombre de usuario</label><input id="memberUsername" placeholder="@usuario"></div><div class="field"><label>Rol</label><select id="memberRole"><option value="translator">Traductor</option><option value="editor">Editor</option><option value="proofreader">Corrector</option><option value="collaborator">Colaborador</option><option value="admin">Administrador</option></select></div><button class="btn primary" id="addTeamMember">Agregar miembro</button>`:'<p class="muted">Solo owner o admin pueden administrar miembros.</p>'}</div><div class="panelCard" style="grid-column:span 2"><h3>Miembros actuales</h3>${S.teamMembers.length?S.teamMembers.map(m=>`<div class="sectionRow"><div><div class="row"><strong>${esc(m.profiles?.display_name||m.profiles?.username||'Miembro')}</strong><span class="badge">${esc(roleLabel(m.role))}</span></div>${m.profiles?.username?`<div class="muted">@${esc(m.profiles.username)}</div>`:''}</div>${isCurrentGroupManager(G.id)&&m.role!=='owner'?`<div class="row"><select data-member-role="${m.user_id}"><option value="admin" ${m.role==='admin'?'selected':''}>Admin</option><option value="translator" ${m.role==='translator'?'selected':''}>Traductor</option><option value="editor" ${m.role==='editor'?'selected':''}>Editor</option><option value="proofreader" ${m.role==='proofreader'?'selected':''}>Corrector</option><option value="collaborator" ${m.role==='collaborator'?'selected':''}>Colaborador</option></select><button class="btn danger" data-remove-member="${m.user_id}">Retirar</button></div>`:'<span class="muted">'+(m.role==='owner'?'Owner protegido':'')+'</span>'}</div>`).join(''):'<div class="muted">No hay miembros registrados.</div>'}</div></div>
 <div class="sectionHead"><div><h2>☕ Apoya al traductor</h2><p>Enlaces públicos de apoyo al equipo.</p></div></div><div class="panelGrid"><div class="panelCard"><h3>Agregar enlace</h3><div class="field"><label>Etiqueta</label><input id="supportLabel" placeholder="Ko-fi, Patreon, PayPal..."></div><div class="field"><label>URL</label><input id="supportUrl" placeholder="https://..."></div><button class="btn primary" id="addSupportLink">Agregar</button></div><div class="panelCard" style="grid-column:span 2"><h3>Enlaces actuales</h3>${G.support_links?.length?G.support_links.map(l=>`<div class="sectionRow"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.label||'Apoyar')} ↗</a><button class="btn danger" data-delete-support="${l.id}">Eliminar</button></div>`).join(''):'<div class="muted">No hay enlaces de apoyo.</div>'}</div></div></main>`}
function studioNewProject(){return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Beta 2</span><h2>Nuevo proyecto</h2><p>Crea la obra original y su traducción en un solo flujo.</p></div><button class="btn" data-v="studio">← Studio</button></div><div class="authShell"><div class="authVisual"><h2>De la ficha al lector.</h2><p>El proyecto empieza en borrador y solo será visible públicamente cuando publiques contenido.</p></div><div class="authPanel"><div class="field"><label>Equipo</label><select id="newGroup">${S.groups.map(g=>`<option value="${g.translator_groups?.id}">${esc(g.translator_groups?.name||'Equipo')}</option>`).join('')}</select></div><div class="field"><label>Título de la obra</label><input id="newNovelTitle" maxlength="220"></div><div class="field"><label>Título original</label><input id="newNovelOriginal" maxlength="220"></div><div class="field"><label>Autor</label><input id="newNovelAuthor" maxlength="160"></div><div class="field"><label>Sinopsis</label><textarea id="newNovelSynopsis" rows="6"></textarea></div><div class="field"><label>Géneros (opcional)</label><input id="newNovelGenres" placeholder="Romance, Comedia, Fantasía"></div><div class="field"><label>Etiquetas (opcional)</label><input id="newNovelTags" placeholder="school-life, isekai, slow-burn"></div><div class="field"><label>Portada</label><input id="newNovelCover" placeholder="https://..."><div class="mediaPicker"><input id="newNovelCoverFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="uploadHint">Subir directamente a NLOBI · máximo 8 MB.</div></div></div><div class="field"><label>Idioma de traducción</label><input id="newTranslationLanguage" value="es"></div><button class="btn primary" id="createProject">Crear proyecto</button></div></div></main>`}
function studioProjectView(){const P=S.studioProject;if(!P)return `${nav()}<main class="wrap"><div class="empty">Cargando proyecto…</div></main>`;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Proyecto</span><h2>${esc(P.novels?.title||P.title||'Proyecto')}</h2><p>${esc(P.translator_groups?.name||'Equipo')} · ${esc(P.status)}</p></div><div class="row"><button class="btn" data-media-open="${P.group_id}" data-target="novel-cover">Biblioteca multimedia</button><button class="btn" data-v="studio">← Studio</button><button class="btn" data-v="studio:import">Importar</button></div></div>
 <div class="panelGrid"><div class="panelCard"><h3>Nuevo volumen</h3><div class="field"><label>Número</label><input id="projectVolumeNumber" type="number" min="0" step=".5" value="${(P.volumes?.length||0)+1}"></div><div class="field"><label>Título</label><input id="projectVolumeTitle"></div><button class="btn primary" id="createVolume">Crear volumen</button></div><div class="panelCard"><h3>Estado de traducción</h3><p class="muted">La traducción puede permanecer activa mientras sus volúmenes/capítulos se controlan por separado.</p><span class="badge">${esc(P.status)}</span></div><div class="panelCard"><h3>Publicación</h3><p class="muted">Solo se muestra públicamente contenido con volumen y sección publicados.</p><span class="badge">Control manual</span></div></div>
 <div class="editorialBox"><h3 style="margin-top:0">Descubrimiento</h3><p class="muted">Opcional. Ayuda a que los lectores encuentren la obra.</p><div class="row"><div class="field" style="flex:1"><label>Géneros</label><input id="projectGenres" value="${esc((P.novels?.genres||[]).join(', '))}" placeholder="Romance, Fantasía"></div><div class="field" style="flex:1"><label>Etiquetas</label><input id="projectTags" value="${esc((P.novels?.tags||[]).join(', '))}" placeholder="school-life, isekai"></div></div><button class="btn" id="saveDiscoveryMeta">Guardar descubrimiento</button></div>
 <div class="editorialBox"><div class="row" style="justify-content:space-between"><div><h3 style="margin:0">Flujo editorial avanzado</h3><p class="muted" style="margin-bottom:0">Opcional. Actívalo solo si quieres historial, comparación y restauración.</p></div><label class="radio"><input type="checkbox" id="editorialModeToggle" ${P.editorial_mode?'checked':''}><span>${P.editorial_mode?'Activado':'Desactivado'}</span></label></div>${P.editorial_mode?'<div class="notice" style="margin-top:12px">Guardar y publicar directamente sigue disponible. Las revisiones son una ayuda opcional.</div>':''}</div>
 <div class="sectionHead"><div><h2>Contenido</h2><p>Volúmenes y secciones del proyecto.</p></div></div><div class="contentTree">${(P.volumes||[]).length?P.volumes.map(v=>`<div class="volumeCard"><div class="row" style="justify-content:space-between"><div><span class="badge">${esc(v.status)}</span><h3 style="margin:7px 0">Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</h3></div><div class="row"><label class="btn">Subir portada <input type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-volume-cover="${v.id}" hidden></label><button class="btn" data-media-open="${P.group_id}" data-target="volume-cover:${v.id}">Elegir portada</button><button class="btn" data-new-section="${v.id}">+ Capítulo</button>${v.status==='published'?`<button class="btn danger" data-volume-status="${v.id}" data-status="hidden">Ocultar volumen</button>`:`<button class="btn primary" data-volume-status="${v.id}" data-status="published">Publicar volumen</button>`}</div></div><div>${(v.sections||[]).length?v.sections.map(sec=>`<div class="sectionRow"><div><div class="row"><span class="badge">${esc(sec.section_type)}</span><span class="badge">${esc(sec.status)}</span></div><strong>${esc(sec.title||'Sin título')}</strong></div><div class="row"><div class="sectionSort"><button class="btn" data-move-section="${sec.id}" data-dir="-1">↑</button><button class="btn" data-move-section="${sec.id}" data-dir="1">↓</button></div>${P.editorial_mode?`<button class="btn" data-preview-section="${sec.id}">Vista previa</button><button class="btn" data-history-section="${sec.id}">Historial</button>`:''}<button class="btn" data-edit-section="${sec.id}">Editar</button>${sec.status==='published'?`<button class="btn danger" data-section-status="${sec.id}" data-status="hidden">Ocultar</button>`:`<button class="btn primary" data-section-status="${sec.id}" data-status="published">Publicar</button>`}</div></div>`).join(''):'<div class="muted">Este volumen aún no tiene secciones.</div>'}</div></div>`).join(''):'<div class="empty">Crea un volumen para comenzar.</div>'}</div>
 ${P.editingSection?studioSectionEditor(P.editingSection):''}
 <div class="sectionHead"><div><h2>Enlaces externos</h2><p>Compra oficial y descargas del proyecto.</p></div></div>
 <div class="linkSections">
  <div class="linkPanel"><h3>❤️ Compra oficial</h3><p class="muted">Los enlaces nuevos quedan pendientes de verificación administrativa.</p><div class="field"><label>Tienda</label><input id="purchaseStore" placeholder="Amazon JP, BookWalker..."></div><div class="field"><label>URL</label><input id="purchaseUrl" placeholder="https://..."></div><div class="row"><div class="field" style="flex:1"><label>Volumen</label><input id="purchaseVolume" type="number" min="0" step=".5"></div><div class="field" style="flex:1"><label>Región</label><input id="purchaseRegion" placeholder="JP"></div></div><div class="row"><div class="field" style="flex:1"><label>Idioma</label><input id="purchaseLanguage" value="ja"></div><div class="field" style="flex:1"><label>Formato</label><input id="purchaseFormat" placeholder="digital / físico"></div></div><button class="btn primary" id="addPurchaseLink">Agregar enlace</button>${P.purchase_links?.length?P.purchase_links.map(l=>`<div class="sectionRow"><div><span class="badge">${l.is_verified?'Verificado':'Pendiente'}</span><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.store_name||'Tienda')}${l.volume_number?` · Vol. ${esc(l.volume_number)}`:''}</a></div><button class="btn danger" data-delete-purchase="${l.id}">Eliminar</button></div>`).join(''):'<div class="muted" style="margin-top:12px">Sin enlaces oficiales.</div>'}</div>
  <div class="linkPanel"><h3>⬇ Descargas</h3><p class="muted">Archivos alojados externamente por el equipo.</p><div class="field"><label>Volumen</label><select id="downloadVolume">${(P.volumes||[]).map(v=>`<option value="${v.id}">Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</option>`).join('')}</select></div><div class="field"><label>Formato</label><input id="downloadFormat" placeholder="EPUB, PDF, DOCX"></div><div class="field"><label>Proveedor</label><input id="downloadProvider" placeholder="Drive, MEGA..."></div><div class="field"><label>URL</label><input id="downloadUrl" placeholder="https://..."></div><button class="btn primary" id="addDownloadLink">Agregar descarga</button>${P.download_links?.length?P.download_links.map(l=>`<div class="sectionRow"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc((l.format||'Archivo').toUpperCase())}${l.provider?` · ${esc(l.provider)}`:''}</a><button class="btn danger" data-delete-download="${l.id}">Eliminar</button></div>`).join(''):'<div class="muted" style="margin-top:12px">Sin descargas.</div>'}</div>
  <div class="linkPanel"><h3>Vista pública</h3><p class="muted">Los lectores verán estos enlaces separados de la lectura integrada.</p><button class="btn" data-open="${P.id}">Ver ficha pública</button></div>
 </div></main>`}
function normalizeBlock(b){if(!b||typeof b!=='object')return{type:'paragraph',text:String(b||'')};const type=b.type||'paragraph';if(type==='image')return{type,url:b.url||'',alt:b.alt||'',caption:b.caption||''};if(type==='ruby')return{type,base:b.base||'',reading:b.reading||''};if(type==='separator')return{type};return{type,text:b.text||''}}
function blockLabel(type){return({paragraph:'Párrafo',heading:'Título',quote:'Cita',image:'Ilustración',separator:'Separador',translator_note:'Nota traductor',ruby:'Ruby/Furigana'}[type]||type)}
function studioSectionEditor(sec){if(!S.blockEditor||S.blockEditor.sectionId!==sec.id)S.blockEditor={sectionId:sec.id,blocks:(Array.isArray(sec.content)?sec.content:[]).map(normalizeBlock)};const blocks=S.blockEditor.blocks;return `<div class="sectionHead"><div><h2>Editor por bloques</h2><p>${esc(sec.title||'')}</p></div></div><div class="panelCard"><div class="field"><label>Título</label><input id="editSectionTitle" value="${esc(sec.title||'')}"></div><div class="field"><label>Tipo</label><select id="editSectionType"><option value="chapter" ${sec.section_type==='chapter'?'selected':''}>Capítulo</option><option value="prologue" ${sec.section_type==='prologue'?'selected':''}>Prólogo</option><option value="interlude" ${sec.section_type==='interlude'?'selected':''}>Interludio</option><option value="epilogue" ${sec.section_type==='epilogue'?'selected':''}>Epílogo</option><option value="afterword" ${sec.section_type==='afterword'?'selected':''}>Afterword</option><option value="extra" ${sec.section_type==='extra'?'selected':''}>Extra</option></select></div><div class="blockPalette"><button class="btn" data-add-block="paragraph">+ Párrafo</button><button class="btn" data-add-block="heading">+ Título</button><button class="btn" data-add-block="quote">+ Cita</button><button class="btn" data-add-block="image">+ Ilustración</button><button class="btn" data-add-block="separator">+ Separador</button><button class="btn" data-add-block="translator_note">+ Nota traductor</button><button class="btn" data-add-block="ruby">+ Ruby</button></div><div class="blockEditor">${blocks.length?blocks.map((b,i)=>renderEditorBlock(b,i)).join(''):'<div class="empty">Añade el primer bloque del capítulo.</div>'}</div>${S.studioProject?.editorial_mode?`<div class="field"><label>Nota de revisión (opcional)</label><input id="revisionNote" maxlength="240" placeholder="Ej. Corrección de estilo"></div><label class="radio"><input type="checkbox" id="createRevisionOnSave" checked><span>Guardar copia anterior en el historial</span></label>`:''}<div class="row" style="margin-top:16px"><button class="btn primary" id="saveSection">Guardar cambios</button>${S.studioProject?.editorial_mode?'<button class="btn" id="previewEditingSection">Vista previa</button>':''}<button class="btn" id="closeSectionEditor">Cerrar</button></div></div>${S.studioProject?.editorial_mode&&S.revisionHistory.length?revisionHistoryPanel():''}${S.revisionPreview?revisionPreviewPanel():''}`}
function renderEditorBlock(b,i){const controls=`<div class="blockActions"><button class="btn" data-move-block="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn" data-move-block="${i}" data-dir="1" ${i===S.blockEditor.blocks.length-1?'disabled':''}>↓</button><button class="btn danger" data-delete-block="${i}">Eliminar</button></div>`;let body='';if(['paragraph','heading','quote','translator_note'].includes(b.type))body=`<textarea rows="${b.type==='paragraph'?5:3}" data-block-text="${i}">${esc(b.text||'')}</textarea>`;else if(b.type==='image')body=`<div class="field"><label>Ilustración</label><input data-block-url="${i}" value="${esc(b.url||'')}" placeholder="https://..."><div class="mediaPicker"><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-block-file="${i}"><div class="uploadHint">Subir directamente al proyecto.</div><button class="btn" type="button" data-media-open="${S.studioProject?.group_id||''}" data-target="block:${i}">Elegir existente</button></div>${b.url?`<img class="mediaPreview" src="${esc(safeMediaUrl(b.url))}" alt="">`:''}</div><div class="field"><label>Texto alternativo</label><input data-block-alt="${i}" value="${esc(b.alt||'')}"></div><div class="field"><label>Pie de imagen</label><input data-block-caption="${i}" value="${esc(b.caption||'')}"></div>`;else if(b.type==='ruby')body=`<div class="row"><div class="field" style="flex:1"><label>Texto base</label><input data-block-base="${i}" value="${esc(b.base||'')}"></div><div class="field" style="flex:1"><label>Lectura</label><input data-block-reading="${i}" value="${esc(b.reading||'')}"></div></div>`;else body='<div class="blockPreview">— Separador —</div>';return `<div class="blockItem"><div class="blockTop"><span class="blockType">${esc(blockLabel(b.type))}</span>${controls}</div>${body}</div>`}
function addEditorBlock(type){if(!S.blockEditor)return;const map={paragraph:{type,text:''},heading:{type,text:''},quote:{type,text:''},image:{type,url:'',alt:'',caption:''},separator:{type},translator_note:{type,text:''},ruby:{type,base:'',reading:''}};S.blockEditor.blocks.push(map[type]||{type:'paragraph',text:''});render()}
function moveEditorBlock(i,dir){if(!S.blockEditor)return;const j=i+dir;if(j<0||j>=S.blockEditor.blocks.length)return;[S.blockEditor.blocks[i],S.blockEditor.blocks[j]]=[S.blockEditor.blocks[j],S.blockEditor.blocks[i]];render()}
function deleteEditorBlock(i){if(!S.blockEditor)return;S.blockEditor.blocks.splice(i,1);render()}
function syncEditorInputs(){if(!S.blockEditor)return;S.blockEditor.blocks.forEach((b,i)=>{if(['paragraph','heading','quote','translator_note'].includes(b.type)){const el=document.querySelector(`[data-block-text="${i}"]`);if(el)b.text=el.value}else if(b.type==='image'){const u=document.querySelector(`[data-block-url="${i}"]`),a=document.querySelector(`[data-block-alt="${i}"]`),c=document.querySelector(`[data-block-caption="${i}"]`);if(u)b.url=u.value;if(a)b.alt=a.value;if(c)b.caption=c.value}else if(b.type==='ruby'){const ba=document.querySelector(`[data-block-base="${i}"]`),r=document.querySelector(`[data-block-reading="${i}"]`);if(ba)b.base=ba.value;if(r)b.reading=r.value}})}
function renderReaderBlock(b){b=normalizeBlock(b);if(b.type==='heading')return `<h2>${esc(b.text||'')}</h2>`;if(b.type==='quote')return `<blockquote>${esc(b.text||'')}</blockquote>`;if(b.type==='separator')return '<hr>';if(b.type==='translator_note')return `<aside class="translatorNote"><b>Nota del traductor</b><div>${esc(b.text||'')}</div></aside>`;if(b.type==='ruby')return `<p><ruby>${esc(b.base||'')}<rt>${esc(b.reading||'')}</rt></ruby></p>`;if(b.type==='image'&&b.url)return `<figure><img src="${esc(safeMediaUrl(b.url))}" alt="${esc(b.alt||'Ilustración')}" loading="lazy">${b.caption?`<figcaption>${esc(b.caption)}</figcaption>`:''}</figure>`;return `<p>${esc(b.text||'')}</p>`}
function studioImport(){return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Importador</span><h2>Importar volumen o capítulo</h2><p>Archivo → Análisis → Estructura → Revisión → Edición → Borrador</p></div><button class="btn" data-v="studio">← Studio</button></div><div class="importShell">${importSteps()}<section class="importPanel">${importStepView()}</section></div></main>`}
function importBlockStats(blocks){const c={paragraph:0,heading:0,quote:0,image:0,separator:0,translator_note:0,ruby:0};(blocks||[]).forEach(b=>{if(c[b.type]!==undefined)c[b.type]++});return c}
function importBlockSummary(blocks){const c=importBlockStats(blocks);return Object.entries(c).filter(([,n])=>n).map(([k,n])=>`${n} ${blockLabel(k).toLowerCase()}`).join(' · ')||'Sin bloques'}
function importStepView(){const I=S.importState;if(I.step==='file')return `<h3>1. Selecciona el archivo</h3><p class="muted">DOCX, EPUB y PDF. DOCX/EPUB conservan estructura editorial cuando es posible; PDF se importa de forma conservadora como texto.</p><label class="dropZone" for="importFile"><div style="font-size:2.2rem">⇧</div><strong>Seleccionar archivo</strong><div class="muted">DOCX · EPUB · PDF</div><input id="importFile" type="file" accept=".docx,.epub,.pdf" hidden></label>${I.file?`<div class="fileBadge">📄 ${esc(I.name)} · ${Math.max(1,Math.round(I.file.size/1024))} KB</div><div class="wizardActions"><span class="muted">${esc(I.type.toUpperCase())}</span><button class="btn primary" id="analyzeImport">Analizar archivo</button></div>`:''}${I.message?`<p class="muted">${esc(I.message)}</p>`:''}`;
if(I.step==='analysis'){const c=importBlockStats(I.parsedBlocks);return `<h3>2. Análisis editorial</h3><div class="importSummary"><div class="infoBox"><small>Archivo</small><b>${esc(I.name)}</b></div><div class="infoBox"><small>Caracteres</small><b>${I.text.length.toLocaleString()}</b></div><div class="infoBox"><small>Bloques detectados</small><b>${I.parsedBlocks.length}</b></div></div><div class="row" style="margin:12px 0;flex-wrap:wrap">${Object.entries(c).filter(([,n])=>n).map(([k,n])=>`<span class="badge">${n} ${esc(blockLabel(k))}</span>`).join('')}</div>${I.warnings?.length?`<div class="notice"><strong>Advertencias</strong>${I.warnings.map(w=>`<div class="muted">• ${esc(w)}</div>`).join('')}</div>`:''}<div class="importPreview">${esc(I.text.slice(0,12000))}${I.text.length>12000?'\n\n[… vista previa recortada …]':''}</div><div class="wizardActions"><button class="btn" data-import-back="file">← Archivo</button><button class="btn primary" id="detectStructure">Detectar capítulos</button></div>`}
if(I.step==='structure')return `<h3>3. Estructura detectada</h3><p class="muted">Ajusta títulos y tipos. Los bloques ricos se conservarán al guardar.</p><div class="sectionEditor">${I.sections.map((x,i)=>`<div class="sectionDraft"><div class="row"><span class="badge">${i+1}</span><input style="flex:1;padding:9px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--text)" data-sec-title="${i}" value="${esc(x.title)}"><select data-sec-type="${i}"><option value="chapter" ${x.section_type==='chapter'?'selected':''}>Capítulo</option><option value="prologue" ${x.section_type==='prologue'?'selected':''}>Prólogo</option><option value="interlude" ${x.section_type==='interlude'?'selected':''}>Interludio</option><option value="epilogue" ${x.section_type==='epilogue'?'selected':''}>Epílogo</option><option value="afterword" ${x.section_type==='afterword'?'selected':''}>Afterword</option><option value="extra" ${x.section_type==='extra'?'selected':''}>Extra</option></select></div><p class="muted">${esc(importBlockSummary(x.blocks))}</p><div class="importPreview" style="max-height:150px">${esc(blocksToPlainText(x.blocks).slice(0,500))}</div></div>`).join('')}</div><div class="wizardActions"><button class="btn" data-import-back="analysis">← Análisis</button><button class="btn primary" id="reviewStructure">Revisar estructura</button></div>`;
if(I.step==='review')return `<h3>4. Revisión</h3><div class="field"><label>Proyecto / traducción</label><select id="importTranslation"><option value="">Selecciona…</option>${S.studioTranslations.map(t=>`<option value="${t.id}" ${I.translationId===t.id?'selected':''}>${esc(t.novels?.title||t.title||'Proyecto')} · ${esc(t.translator_groups?.name||'Equipo')}</option>`).join('')}</select></div><div class="row"><div class="field" style="flex:1"><label>Número de volumen</label><input id="importVolumeNumber" type="number" min="0" step="0.5" value="${esc(I.volumeNumber)}"></div><div class="field" style="flex:2"><label>Título del volumen</label><input id="importVolumeTitle" value="${esc(I.volumeTitle)}"></div></div><div class="notice"><strong>${I.sections.length} secciones · ${I.sections.reduce((n,x)=>n+(x.blocks?.length||0),0)} bloques</strong><div class="muted">Todo se guardará como borrador. Nada se publicará automáticamente.</div></div><div class="wizardActions"><button class="btn" data-import-back="structure">← Estructura</button><button class="btn primary" id="goEditImport">Continuar a edición</button></div>`;
if(I.step==='edit')return `<h3>5. Revisión de bloques</h3><p class="muted">Puedes corregir el texto rápidamente aquí. La estructura rica se conserva; después podrás afinar bloque por bloque con el editor Beta 8.</p><div class="sectionEditor">${I.sections.map((x,i)=>`<div class="sectionDraft"><div class="row"><strong>${esc(x.title)}</strong><span class="badge">${esc(x.section_type)}</span></div><div class="muted">${esc(importBlockSummary(x.blocks))}</div><textarea data-sec-body="${i}">${esc(blocksToPlainText(x.blocks))}</textarea><label class="radio"><input type="checkbox" data-rebuild-plain="${i}"><span>Reemplazar estructura rica por el texto editado como párrafos simples</span></label></div>`).join('')}</div><div class="wizardActions"><button class="btn" data-import-back="review">← Revisión</button><button class="btn primary" id="goPublishImport">Revisar guardado</button></div>`;
return `<h3>6. Guardar borradores</h3><p class="muted">Esta acción escribe los bloques detectados en Supabase con estado <b>draft</b>.</p><div class="notice"><strong>${esc(I.name)}</strong><div class="muted">${I.sections.length} secciones · ${I.sections.reduce((n,x)=>n+(x.blocks?.length||0),0)} bloques → Volumen ${esc(I.volumeNumber)}</div></div>${I.message?`<div class="status ${/completada/i.test(I.message)?'ok':'bad'}" style="margin-top:12px">${esc(I.message)}</div>`:''}<div class="wizardActions"><button class="btn" data-import-back="edit">← Edición</button><button class="btn primary" id="saveImportDrafts" ${I.busy?'disabled':''}>${I.busy?'Guardando…':'Guardar como borrador'}</button></div>`}
function notificationTypeLabel(t){return({new_publication:'Nueva publicación',comment_reply:'Respuesta',team_application:'Equipo',system:'Sistema'}[t]||'Aviso')}
function notificationAction(n){if(n.section_id&&n.translation_id)return `<button class="btn primary" data-note-open-section="${n.section_id}" data-translation="${n.translation_id}">Abrir capítulo</button>`;if(n.translation_id)return `<button class="btn primary" data-open="${n.translation_id}">Ver obra</button>`;if(n.notification_type==='team_application')return `<button class="btn" data-v="auth">Ver mi cuenta</button>`;if(n.notification_type==='system')return `<button class="btn" data-v="beta">Abrir Beta</button>`;return''}
function notifications(){const unread=S.notes.filter(x=>!x.read_at).length,P=S.notificationPrefs;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><h2>Notificaciones</h2><p>Novedades de tus lecturas, comentarios, equipos y cuenta.</p></div><div class="row">${unread?`<button class="btn primary" id="markAllNotificationsRead">Marcar todas leídas</button>`:''}<button class="btn" id="clearReadNotifications">Limpiar leídas</button></div></div><div class="notificationPrefs"><label class="notificationPref"><input type="checkbox" data-notification-pref="new_publications" ${P.new_publications?'checked':''}> <strong>Nuevas publicaciones</strong><div class="muted">Capítulos de obras, traducciones y equipos que sigues.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="comment_replies" ${P.comment_replies?'checked':''}> <strong>Respuestas</strong><div class="muted">Cuando alguien responde a uno de tus comentarios.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="team_updates" ${P.team_updates?'checked':''}> <strong>Equipos</strong><div class="muted">Aprobación o rechazo de solicitudes de equipo.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="system_updates" ${P.system_updates?'checked':''}> <strong>Sistema</strong><div class="muted">Resolución de reportes Beta y avisos importantes.</div></label></div><div class="list">${S.notes.length?S.notes.map(n=>`<div class="notice notificationItem ${!n.read_at?'unread':''}"><div class="row"><span class="badge">${esc(notificationTypeLabel(n.notification_type))}</span><strong>${esc(n.title)}</strong>${!n.read_at?'<span class="badge">Nueva</span>':''}</div><div class="muted">${esc(n.body||'')}</div><div class="muted">${esc((n.created_at||'').replace('T',' ').slice(0,16))}</div><div class="notificationActions">${notificationAction(n)}${!n.read_at?`<button class="btn" data-read="${n.id}">Marcar leída</button>`:''}<button class="btn danger" data-delete-note="${n.id}">Eliminar</button></div></div>`).join(''):'<div class="empty"><div class="emptyArt">🔔</div><strong>Todo al día</strong><div>No tienes notificaciones.</div></div>'}</div></main>`}

function betaView(){
 if(!S.user)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">🧪</div><strong>Beta 1</strong><div>Inicia sesión para ejecutar pruebas y enviar feedback.</div><div style="margin-top:12px"><button class="btn primary" data-v="auth">Iniciar sesión</button></div></div></main>`;
 const checks=S.betaChecks.length?`<div class="list">${S.betaChecks.map(x=>`<div class="notice"><div class="row"><span class="badge">${x.ok?'OK':'Fallo'}</span><strong>${esc(x.label)}</strong></div><div class="muted">${esc(x.detail||'')}</div></div>`).join('')}</div>`:'<div class="empty"><div class="emptyArt">✓</div><strong>Aún no ejecutas el diagnóstico</strong><div>Las pruebas son de lectura y no modifican contenido.</div></div>';
 return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Beta 1</span><h2>Centro de pruebas</h2><p>Comprueba las conexiones principales y reporta cualquier problema desde aquí.</p></div><button class="btn primary" id="runBetaChecks">Ejecutar diagnóstico</button></div>
 <div class="panelGrid"><div class="panelCard"><h3>Estado de la sesión</h3><p class="muted">${S.user?`Conectado como ${esc(S.user.email||S.profile?.display_name||'usuario')}`:'Sin sesión'}</p><span class="badge">${S.online?'En línea':'Sin conexión'}</span></div><div class="panelCard"><h3>Biblioteca</h3><p class="muted">${S.library.length} títulos sincronizados.</p></div><div class="panelCard"><h3>Studio</h3><p class="muted">${S.groups.length?`${S.groups.length} equipos vinculados.`:'Sin equipo aprobado.'}</p></div><div class="panelCard"><h3>QA Beta 18</h3><p class="muted">RLS endurecido, progreso sin regresiones, filtros restaurados y publicación encadenada protegida.</p><span class="badge">Pre-producción</span></div></div>
 <div class="sectionHead"><div><h2>Diagnóstico E2E</h2><p>Frontend → Supabase → sesión → perfil → biblioteca → Studio.</p></div></div>${checks}
 <div class="sectionHead"><div><h2>Enviar feedback</h2><p>El reporte quedará asociado únicamente a tu cuenta.</p></div></div>
 <div class="authShell" style="grid-template-columns:.7fr 1.3fr"><div class="authVisual"><h2>Ayuda a pulir NLOBI</h2><p>Describe qué estabas haciendo y qué esperabas que ocurriera.</p></div><div class="authPanel"><div class="field"><label>Categoría</label><select id="betaCategory"><option value="bug">Error</option><option value="ux">Diseño / experiencia</option><option value="content">Contenido</option><option value="performance">Rendimiento</option><option value="other">Otro</option></select></div><div class="field"><label>Título</label><input id="betaTitle" maxlength="120" placeholder="Ej. No puedo guardar en la biblioteca"></div><div class="field"><label>Descripción</label><textarea id="betaDescription" rows="6" maxlength="4000" placeholder="Pasos para reproducir el problema..."></textarea></div><button class="btn primary" id="submitBetaFeedback">Enviar reporte</button></div></div>
 ${S.betaFeedback.length?`<div class="sectionHead"><div><h2>Mis reportes</h2></div></div><div class="list">${S.betaFeedback.map(f=>`<div class="notice"><div class="row"><span class="badge">${esc(f.status)}</span><strong>${esc(f.title)}</strong></div><div class="muted">${esc(f.category)} · ${esc((f.created_at||'').slice(0,10))}</div><p>${esc(f.description)}</p>${f.admin_note?`<div class="muted">Nota admin: ${esc(f.admin_note)}</div>`:''}</div>`).join('')}</div>`:''}
 </main>`
}
function adminBeta(){return `<div class="list">${S.adminBetaFeedback.length?S.adminBetaFeedback.map(f=>`<div class="adminApp"><div class="row"><span class="badge">${esc(f.status)}</span><strong>${esc(f.title)}</strong></div><div class="muted">${esc(f.category)} · ${esc((f.created_at||'').replace('T',' ').slice(0,19))}</div><p>${esc(f.description)}</p><div class="muted">${esc(f.profiles?.display_name||f.profiles?.username||f.user_id)}</div>${f.admin_note?`<div class="notice">Nota admin: ${esc(f.admin_note)}</div>`:''}<div class="row"><button class="btn" data-beta-status="${f.id}" data-status="reviewing">Revisando</button><button class="btn primary" data-beta-status="${f.id}" data-status="resolved">Resuelto</button><button class="btn danger" data-beta-status="${f.id}" data-status="dismissed">Descartar</button></div></div>`).join(''):'<div class="empty">No hay reportes Beta.</div>'}</div>`}

function publicProfileView(){const P=S.publicProfile;if(!P)return `${nav()}<main class="wrap"><div class="empty">Cargando perfil…</div></main>`;return `${nav()}<main class="wrap">${status()}<section class="profileHero"><div class="profileAvatar">${P.avatar_url?`<img src="${esc(safeUrl(P.avatar_url))}" alt="${esc(P.display_name||P.username||'Perfil')}">`:esc((P.display_name||P.username||'U').slice(0,1))}</div><div><h1 style="font-family:Georgia,serif;margin:0 0 6px">${esc(P.display_name||P.username||'Usuario')}</h1>${P.username?`<div class="muted">@${esc(P.username)}</div>`:''}<p>${esc(P.bio||'Sin biografía pública.')}</p></div></section>${P.public_library?`<div class="sectionHead"><div><h2>Biblioteca pública</h2><p>Lecturas que esta persona decidió compartir.</p></div></div>${P.library?.length?`<div class="libraryList">${P.library.map(x=>{const t=x.translations;return `<div class="libraryCard"><div class="libraryThumb">${t?.novels?.cover_url?`<img src="${esc(safeUrl(t.novels.cover_url))}" alt="">`:''}</div><div class="libraryMeta"><span class="statusPill">${esc(statusLabel(x.status))}</span><h3>${esc(t?.novels?.title||t?.title||'Novela')}</h3><div class="muted">${esc(t?.translator_groups?.name||'Traducción')}</div></div><button class="btn" data-open="${x.translation_id}">Ver obra</button></div>`}).join('')}</div>`:'<div class="empty">No hay lecturas públicas.</div>'}`:'<div class="sectionHead"><div><h2>Biblioteca</h2></div></div><div class="empty">Esta biblioteca es privada.</div>'}${P.public_activity?`<div class="sectionHead"><div><h2>Actividad reciente</h2><p>Progreso que esta persona eligió compartir.</p></div></div><div class="activityList">${P.activity?.length?P.activity.map(a=>`<div class="activityItem"><div class="row"><span class="badge">${esc(Math.round(Number(a.progress_percent||0)))}%</span><strong>${esc(a.translations?.novels?.title||a.translations?.title||'Lectura')}</strong></div><div class="muted">Actualizado ${esc((a.updated_at||'').replace('T',' ').slice(0,16))}</div></div>`).join(''):'<div class="empty">Sin actividad pública reciente.</div>'}</div>`:'<div class="sectionHead"><div><h2>Actividad</h2></div></div><div class="empty">La actividad de lectura es privada.</div>'}</main>`}
