function resetImport(){S.importState={step:'file',file:null,type:'',name:'',text:'',parsedBlocks:[],sections:[],warnings:[],translationId:'',volumeNumber:'1',volumeTitle:'',busy:false,message:''}}
function selectImportFile(file){if(!file)return;const ext=(file.name.split('.').pop()||'').toLowerCase();if(!['docx','epub','pdf'].includes(ext)){toast('Formato no admitido. Usa DOCX, EPUB o PDF.','bad');return}resetImport();S.importState.file=file;S.importState.name=file.name;S.importState.type=ext;render()}
function loadScriptOnce(src,test){return new Promise((resolve,reject)=>{if(test())return resolve();const sc=document.createElement('script');sc.src=src;sc.async=true;sc.onload=resolve;sc.onerror=()=>reject(new Error('No se pudo cargar la librería requerida.'));document.head.appendChild(sc)})}
async function analyzeImportFile(){const I=S.importState;if(!I.file)return;I.busy=true;I.message='Analizando…';render();try{let parsed;if(I.type==='docx')parsed=await parseDocxRich(I.file);else if(I.type==='epub')parsed=await parseEpubRich(I.file);else parsed=await parsePdfRich(I.file);I.text=normalizeImportedText(parsed.text);I.parsedBlocks=(parsed.blocks||[]).map(normalizeImportBlock);I.warnings=parsed.warnings||[];if(!I.text.trim()&&!I.parsedBlocks.length)throw new Error('No se pudo extraer contenido del archivo.');I.step='analysis';I.message=''}catch(e){I.message=friendlyError(e,'No se pudo analizar el archivo.')}finally{I.busy=false;render()}}
function normalizeImportBlock(b){if(!b||typeof b!=='object')return{type:'paragraph',text:String(b||'')};if(b.type==='image')return{type:'image',url:b.url||'',alt:b.alt||'',caption:b.caption||''};if(b.type==='ruby')return{type:'ruby',base:b.base||'',reading:b.reading||''};if(b.type==='separator')return{type:'separator'};return{type:['heading','quote','translator_note','paragraph'].includes(b.type)?b.type:'paragraph',text:String(b.text||'')}}
function importTextBlock(text,type='paragraph'){text=String(text||'').trim();if(!text)return null;if(/^(?:nota del traductor|translator(?:'s)? note|t\/?n)\s*[:：-]\s*/i.test(text))return{type:'translator_note',text:text.replace(/^(?:nota del traductor|translator(?:'s)? note|t\/?n)\s*[:：-]\s*/i,'').trim()};if(/^(\*{3,}|-{3,}|—{3,}|※{3,}|◆{3,}|◇{3,})$/.test(text))return{type:'separator'};return{type,text}}
function htmlNodesToBlocks(root){const out=[];const nodes=[...root.querySelectorAll('h1,h2,h3,h4,h5,h6,p,blockquote,img,hr,ruby')];for(const n of nodes){if(n.closest('ruby')&&n.tagName.toLowerCase()!=='ruby')continue;const tag=n.tagName.toLowerCase();if(/^h[1-6]$/.test(tag)){const b=importTextBlock(n.textContent,'heading');if(b)out.push(b)}else if(tag==='blockquote'){const b=importTextBlock(n.textContent,'quote');if(b)out.push(b)}else if(tag==='img'){const src=n.getAttribute('src')||'';if(src)out.push({type:'image',url:src,alt:n.getAttribute('alt')||'',caption:n.getAttribute('title')||''})}else if(tag==='hr')out.push({type:'separator'});else if(tag==='ruby'){const rt=n.querySelector('rt')?.textContent?.trim()||'';const clone=n.cloneNode(true);clone.querySelectorAll('rt,rp').forEach(x=>x.remove());const base=clone.textContent.trim();if(base)out.push({type:'ruby',base,reading:rt})}else{const b=importTextBlock(n.textContent,'paragraph');if(b)out.push(b)}}return out}
function blocksToPlainText(blocks){return (blocks||[]).map(b=>{if(b.type==='image')return b.caption?`[Ilustración: ${b.caption}]`:'[Ilustración]';if(b.type==='separator')return'***';if(b.type==='ruby')return b.reading?`${b.base}（${b.reading}）`:b.base;return b.text||''}).filter(Boolean).join('\n\n')}
async function parseDocxRich(file){await loadScriptOnce('https://cdn.jsdelivr.net/npm/mammoth@1.8.0/mammoth.browser.min.js',()=>!!window.mammoth);const warnings=[];const r=await window.mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()},{convertImage:window.mammoth.images.imgElement(async image=>{const base64=await image.read('base64');if(base64.length>2000000){warnings.push('Se omitió una imagen DOCX de más de ~1.5 MB para evitar inflar el capítulo.');return{src:''}}return{src:`data:${image.contentType||'image/png'};base64,${base64}`}})});const doc=new DOMParser().parseFromString(`<body>${r.value||''}</body>`,'text/html');doc.querySelectorAll('script,style').forEach(n=>n.remove());const blocks=htmlNodesToBlocks(doc.body);warnings.push(...(r.messages||[]).filter(x=>x.type==='warning').map(x=>x.message).slice(0,8));return{text:blocksToPlainText(blocks),blocks,warnings}}
function normalizeZipPath(base,rel){if(/^(?:https?:|data:)/i.test(rel))return rel;const parts=(base+rel).split('/'),out=[];for(const p of parts){if(!p||p==='.')continue;if(p==='..')out.pop();else out.push(p)}return out.join('/')}
function mimeFromPath(p){const e=(p.split('.').pop()||'').toLowerCase();return e==='jpg'||e==='jpeg'?'image/jpeg':e==='gif'?'image/gif':e==='webp'?'image/webp':e==='svg'?'image/svg+xml':'image/png'}
async function parseEpubRich(file){await loadScriptOnce('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js',()=>!!window.JSZip);const zip=await window.JSZip.loadAsync(await file.arrayBuffer()),warnings=[];let paths=[];const container=zip.file('META-INF/container.xml');if(container){const xml=new DOMParser().parseFromString(await container.async('text'),'application/xml');const root=xml.querySelector('rootfile')?.getAttribute('full-path');if(root&&zip.file(root)){const base=root.includes('/')?root.slice(0,root.lastIndexOf('/')+1):'';const opf=new DOMParser().parseFromString(await zip.file(root).async('text'),'application/xml');const manifest={};opf.querySelectorAll('manifest item').forEach(n=>manifest[n.getAttribute('id')]={href:n.getAttribute('href')});opf.querySelectorAll('spine itemref').forEach(n=>{const it=manifest[n.getAttribute('idref')];if(it?.href)paths.push(normalizeZipPath(base,it.href))})}}if(!paths.length)paths=Object.keys(zip.files).filter(p=>/\.(xhtml|html|htm)$/i.test(p));const all=[];for(const p of paths){const f=zip.file(p);if(!f)continue;const doc=new DOMParser().parseFromString(await f.async('text'),'text/html');doc.querySelectorAll('script,style,nav').forEach(n=>n.remove());const base=p.includes('/')?p.slice(0,p.lastIndexOf('/')+1):'';for(const img of doc.querySelectorAll('img')){const src=img.getAttribute('src')||'';if(!src||/^(?:https?:|data:)/i.test(src))continue;const zp=normalizeZipPath(base,decodeURIComponent(src.split('#')[0]));const zf=zip.file(zp);if(!zf){warnings.push(`No se encontró una imagen EPUB: ${src}`);continue}const b64=await zf.async('base64');if(b64.length>2000000){warnings.push(`Se omitió una imagen EPUB grande: ${src}`);img.remove();continue}img.setAttribute('src',`data:${mimeFromPath(zp)};base64,${b64}`)}const blocks=htmlNodesToBlocks(doc.body);if(blocks.length){if(all.length)all.push({type:'separator'});all.push(...blocks)}}return{text:blocksToPlainText(all),blocks:all,warnings}}
async function parsePdfRich(file){await loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',()=>!!window.pdfjsLib);window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,out=[];for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i);const tc=await pg.getTextContent();const text=tc.items.map(x=>x.str).join(' ').trim();if(text)out.push({type:'paragraph',text});if(i<pdf.numPages)out.push({type:'separator'})}return{text:blocksToPlainText(out),blocks:out,warnings:['PDF conserva texto y páginas, pero no puede garantizar estilos, imágenes o ruby. Revisa el resultado antes de publicar.']}}
function normalizeImportedText(t){return String(t||'').replace(/\r\n?/g,'\n').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
function detectSectionType(t){t=t.toLowerCase();if(/pr[oó]logo|prologue|プロローグ/.test(t))return'prologue';if(/ep[ií]logo|epilogue|エピローグ/.test(t))return'epilogue';if(/interludio|interlude|幕間/.test(t))return'interlude';if(/afterword|あとがき|posfacio/.test(t))return'afterword';if(/extra|bonus|特典|番外/.test(t))return'extra';return'chapter'}
function isSectionHeading(text){return /^\s*((?:cap[ií]tulo|chapter)\s*[0-9ivxlcdm一二三四五六七八九十百]+.*|第\s*[0-9一二三四五六七八九十百]+\s*[章話].*|pr[oó]logo.*|prologue.*|プロローグ.*|ep[ií]logo.*|epilogue.*|エピローグ.*|interludio.*|interlude.*|幕間.*|afterword.*|あとがき.*|extra.*|bonus.*|番外.*)\s*$/i.test(String(text||'').trim())}
function detectSectionsRich(blocks,text){const source=(blocks||[]).length?blocks:textBlocks(text),out=[];let title='Capítulo 1',buf=[];const push=()=>{const clean=buf.filter(Boolean);if(clean.length)out.push({title,section_type:detectSectionType(title),blocks:clean,body:blocksToPlainText(clean)})};for(const b of source){if(b.type==='heading'&&isSectionHeading(b.text)){push();title=String(b.text).trim();buf=[]}else buf.push(normalizeImportBlock(b))}push();if(!out.length&&source.length)out.push({title:'Capítulo 1',section_type:'chapter',blocks:source.map(normalizeImportBlock),body:blocksToPlainText(source)});return out.map((x,i)=>({...x,section_number:i+1}))}
function detectSections(text){return detectSectionsRich([],text)}
function syncStructureFields(){$$('[data-sec-title]').forEach(el=>{const i=+el.dataset.secTitle;if(S.importState.sections[i])S.importState.sections[i].title=el.value.trim()||`Sección ${i+1}`});$$('[data-sec-type]').forEach(el=>{const i=+el.dataset.secType;if(S.importState.sections[i])S.importState.sections[i].section_type=el.value})}
function syncImportTarget(){const t=$('#importTranslation'),v=$('#importVolumeNumber'),n=$('#importVolumeTitle');if(t)S.importState.translationId=t.value;if(v)S.importState.volumeNumber=v.value||'1';if(n)S.importState.volumeTitle=n.value.trim()}
function syncEditedBodies(){$$('[data-sec-body]').forEach(el=>{const i=+el.dataset.secBody;if(!S.importState.sections[i])return;S.importState.sections[i].body=el.value;const rebuild=document.querySelector(`[data-rebuild-plain="${i}"]`);if(rebuild?.checked)S.importState.sections[i].blocks=textBlocks(el.value)})}
function syncImportFields(){syncStructureFields();syncImportTarget();syncEditedBodies()}
function textBlocks(body){return String(body||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).map(x=>importTextBlock(x,'paragraph')).filter(Boolean)}
async function loadStudioData(){if(!S.groups.length){S.studioTranslations=[];return}const ids=S.groups.map(g=>g.translator_groups?.id).filter(Boolean);if(!ids.length)return;S.studioTranslations=await jreq(`/rest/v1/translations?group_id=in.(${ids.join(',')})&select=id,title,status,language_code,group_id,editorial_mode,novels(id,title),translator_groups(id,name)&order=updated_at.desc`)||[]}
async function saveImportDrafts(){const I=S.importState;if(I.busy)return;I.busy=true;I.message='';render();try{const tr=S.studioTranslations.find(x=>x.id===I.translationId);if(!tr)throw new Error('Proyecto no disponible.');const gid=tr.group_id||tr.translator_groups?.id;const job=await jreq('/rest/v1/import_jobs',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({group_id:gid,created_by:S.user.id,filename:I.name,file_type:I.type,status:'processing',result:{section_count:I.sections.length}})});let vols=await jreq(`/rest/v1/volumes?translation_id=eq.${I.translationId}&volume_number=eq.${encodeURIComponent(I.volumeNumber)}&select=id&limit=1`);let volume=vols?.[0];if(!volume){const created=await jreq('/rest/v1/volumes',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({translation_id:I.translationId,volume_number:Number(I.volumeNumber),title:I.volumeTitle||null,status:'draft'})});volume=created?.[0]}if(!volume?.id)throw new Error('No se pudo resolver el volumen.');const payload=[];for(let i=0;i<I.sections.length;i++){const x=I.sections[i],raw=(x.blocks?.length?x.blocks.map(normalizeImportBlock):textBlocks(x.body));const content=await materializeImportedImages(raw,gid,`volume-${volume.id}-section-${i+1}`);payload.push({volume_id:volume.id,section_type:x.section_type,section_number:x.section_number||i+1,title:x.title,content,sort_order:i+1,status:'draft'})}await jreq('/rest/v1/sections',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});if(job?.[0]?.id)await jreq(`/rest/v1/import_jobs?id=eq.${job[0].id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'completed',result:{section_count:payload.length,volume_id:volume.id,translation_id:I.translationId},updated_at:new Date().toISOString()})});I.busy=false;I.message=`Importación completada: ${payload.length} secciones guardadas como borrador.`;render()}catch(e){I.busy=false;I.message=friendlyError(e,'No se pudo guardar la importación.');render()}}


function setReaderPref(k,v){S.readerPrefs[k]=v;localStorage.setItem(k==='fontSize'?'reader_font':k==='theme'?'reader_theme':'reader_width',String(v));render()}
async function loadFollows(){if(!S.user){S.follows=[];return}S.follows=await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&select=target_type,target_id,created_at`)||[]}
async function toggleFollow(type,id){try{if(!S.user){go('auth');return}if(isFollowing(type,id)){await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&target_type=eq.${type}&target_id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/follows',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:S.user.id,target_type:type,target_id:id})})}await loadFollows();render()}catch(e){toast(friendlyError(e),'bad')}}
async function loadReaderComments(sectionId){const rows=await jreq(`/rest/v1/comments?section_id=eq.${sectionId}&select=id,section_id,user_id,parent_id,body,is_spoiler,created_at,profiles(id,username,display_name),comment_reactions(user_id,reaction)&order=created_at.asc`);S.readerComments=(rows||[]).map(c=>({...c,like_count:(c.comment_reactions||[]).filter(r=>r.reaction==='like').length,liked_by_me:!!S.user&&(c.comment_reactions||[]).some(r=>r.user_id===S.user.id&&r.reaction==='like')}))}
async function postComment(parentId=null,bodyOverride=null){try{if(!S.user||!S.readerSection)return;const body=(bodyOverride ?? $('#newCommentBody')?.value?.trim() ?? '');if(body.length<1){toast('Escribe un comentario.','bad');return}const is_spoiler=parentId?false:!!$('#newCommentSpoiler')?.checked;await jreq('/rest/v1/comments',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({section_id:S.readerSection.id,user_id:S.user.id,parent_id:parentId,body,is_spoiler})});await loadReaderComments(S.readerSection.id);render();toast('Comentario publicado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function replyComment(id){const body=prompt('Escribe tu respuesta:');if(body&&body.trim())await postComment(id,body.trim())}
async function toggleCommentLike(id){try{if(!S.user){go('auth');return}const c=S.readerComments.find(x=>x.id===id);if(c?.liked_by_me){await jreq(`/rest/v1/comment_reactions?comment_id=eq.${id}&user_id=eq.${S.user.id}&reaction=eq.like`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/comment_reactions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,user_id:S.user.id,reaction:'like'})})}await loadReaderComments(S.readerSection.id);render()}catch(e){toast(friendlyError(e),'bad')}}
async function reportComment(id){if(!S.user){go('auth');return}const reason=prompt('Motivo del reporte:');if(!reason?.trim())return;try{await jreq('/rest/v1/comment_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,reporter_id:S.user.id,reason:reason.trim(),status:'pending'})});toast('Reporte enviado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function openDetail(id){if(String(id).startsWith('demo-')){S.currentDetail=null;go('detail:'+id);return}try{S.currentDetail=await loadTranslationDetail(id);go('detail:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadTranslationDetail(id){const rows=await jreq(`/rest/v1/translations?id=eq.${id}&select=id,title,status,language_code,popularity_score,updated_at,novels(id,title,synopsis,cover_url,author_name,genres,tags),translator_groups(id,name),volumes(id,volume_number,title,status,cover_url,sections(id,title,section_type,section_number,status,sort_order),download_links(id,format,provider,url))&limit=1`);const x=rows?.[0]||null;if(!x)return null;const [purchase,support,downloads]=await Promise.all([jreq(`/rest/v1/purchase_links?novel_id=eq.${x.novels?.id}&is_verified=eq.true&select=id,volume_number,store_name,region,language_code,format,url&order=volume_number.asc`),x.translator_groups?.id?jreq(`/rest/v1/support_links?group_id=eq.${x.translator_groups.id}&select=id,label,url&order=created_at.asc`):Promise.resolve([]),jreq(`/rest/v1/download_links?volume_id=in.(${(x.volumes||[]).map(v=>v.id).join(',')||'00000000-0000-0000-0000-000000000000'})&select=id,volume_id,format,provider,url&order=created_at.asc`)]);x.links={purchase:purchase||[],support:support||[],downloads:downloads||[]};return x}

async function uploadPersonalAvatar(e){try{const file=e.target.files?.[0];if(!file||!S.user)return;const url=await storageUpload(file,`users/${S.user.id}/avatar/${storageName('avatar',file)}`,false);const input=$('#profileAvatarUrl');if(input)input.value=url;toast('Avatar subido. Guarda el perfil para aplicarlo.','ok')}catch(err){toast(friendlyError(err),'bad')}}
async function savePersonalProfile(){try{if(!S.user)return;const username=$('#profileUsername')?.value.trim().replace(/^@/,'')||null;if(username&&(!/^[A-Za-z0-9_.-]{3,40}$/.test(username))){toast('El nombre de usuario debe tener 3-40 caracteres y usar letras, números, punto, guion o guion bajo.','bad');return}const body={display_name:$('#profileDisplayName')?.value.trim()||null,username,avatar_url:$('#profileAvatarUrl')?.value.trim()||null,bio:$('#profileBio')?.value.trim()||null,public_library:!!$('#profilePublicLibrary')?.checked,public_activity:!!$('#profilePublicActivity')?.checked,updated_at:new Date().toISOString()};await jreq(`/rest/v1/profiles?id=eq.${S.user.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await loadUser();render();toast('Perfil actualizado.','ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese nombre de usuario ya está en uso.':friendlyError(e),'bad')}}
async function openPublicProfile(id){try{const rows=await jreq(`/rest/v1/profiles?id=eq.${id}&select=id,username,display_name,avatar_url,bio,public_library,public_activity&limit=1`);const p=rows?.[0];if(!p)throw new Error('Perfil no encontrado.');let library=[],activity=[];if(p.public_library)library=await jreq(`/rest/v1/library_entries?user_id=eq.${id}&select=translation_id,status,translations(id,title,novels(id,title,cover_url),translator_groups(id,name))&order=updated_at.desc&limit=50`)||[];if(p.public_activity)activity=await jreq(`/rest/v1/reading_progress?user_id=eq.${id}&select=translation_id,progress_percent,updated_at,translations(id,title,novels(id,title))&order=updated_at.desc&limit=20`)||[];S.publicProfile={...p,library,activity};go('profile:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function openGroup(id){try{const rows=await jreq(`/rest/v1/translator_groups?id=eq.${id}&select=id,slug,name,description,avatar_url,banner_url,primary_color,secondary_color&limit=1`);const g=rows?.[0];if(!g)throw new Error('Equipo no encontrado.');const [translations,support]=await Promise.all([jreq(`/rest/v1/translations?group_id=eq.${id}&status=in.(active,complete)&select=id,title,status,language_code,novels(id,title,synopsis,cover_url),translator_groups(id,name)&order=updated_at.desc`),jreq(`/rest/v1/support_links?group_id=eq.${id}&select=id,label,url&order=created_at.asc`)]);S.publicGroup={...g,translations:translations||[],support_links:support||[]};go('group:'+id)}catch(e){toast(friendlyError(e),'bad')}}


function roleLabel(role){return({owner:'Owner',admin:'Admin',translator:'Traductor',editor:'Editor',proofreader:'Corrector',collaborator:'Colaborador'}[role]||role||'Miembro')}
function myGroupRole(groupId){return S.groups.find(g=>g.translator_groups?.id===groupId)?.role||null}
function isCurrentGroupManager(groupId){return ['owner','admin'].includes(myGroupRole(groupId))||S.admin}
async function loadTeamMembers(groupId){S.teamMembers=await jreq(`/rest/v1/group_members?group_id=eq.${groupId}&select=group_id,user_id,role,profiles(id,username,display_name,avatar_url)&order=role.asc`)||[]}
async function resolveProfileByUsername(value){const raw=String(value||'').trim().replace(/^@/,'');if(!raw)return null;let rows=await jreq(`/rest/v1/profiles?username=eq.${encodeURIComponent(raw)}&select=id,username,display_name&limit=1`);if(rows?.[0])return rows[0];if(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(raw)){rows=await jreq(`/rest/v1/profiles?id=eq.${raw}&select=id,username,display_name&limit=1`);return rows?.[0]||null}return null}
async function addTeamMember(){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)){toast('No tienes permiso para administrar miembros.','bad');return}const profile=await resolveProfileByUsername($('#memberUsername')?.value);if(!profile){toast('No encontramos ese nombre de usuario.','bad');return}const role=$('#memberRole')?.value||'translator';if(role==='owner'){toast('El owner no se asigna desde aquí.','bad');return}await jreq('/rest/v1/group_members',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,user_id:profile.id,role})});await loadTeamMembers(G.id);await loadStudioData();render();toast(`${profile.display_name||profile.username||'Usuario'} fue agregado al equipo.`,'ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese usuario ya pertenece al equipo.':friendlyError(e),'bad')}}
async function changeTeamMemberRole(userId,role){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)||role==='owner')return;const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner')return;await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({role})});await loadTeamMembers(G.id);await loadStudioData();render();toast('Rol actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function removeTeamMember(userId){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id))return;const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner'){toast('El owner del equipo está protegido.','bad');return}await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadTeamMembers(G.id);await loadStudioData();render();toast('Acceso retirado.','ok')}catch(e){toast(friendlyError(e),'bad')}}

async function openMediaLibrary(groupId,target=null){try{if(!groupId)throw new Error('No se pudo determinar el equipo.');S.mediaGroupId=groupId;S.mediaTarget=target;S.mediaQuery='';S.mediaLoading=true;go('studio:media:'+groupId);render();S.mediaFiles=await storageWalk(`teams/${groupId}`);S.mediaLoading=false;render()}catch(e){S.mediaLoading=false;toast(friendlyError(e),'bad')}}
function mediaBack(){const gid=S.mediaGroupId,target=S.mediaTarget;S.mediaTarget=null;if(target&&S.studioProject?.group_id===gid)go('studio:project:'+S.studioProject.id);else if(S.studioTeam?.id===gid)go('studio:team:'+gid);else go('studio')}
async function uploadMediaLibraryFile(file){try{if(!file||!S.mediaGroupId)return;const path=`teams/${S.mediaGroupId}/library/${storageName('media',file)}`;await storageUpload(file,path,false);S.mediaFiles=await storageWalk(`teams/${S.mediaGroupId}`);render();toast('Imagen añadida a la biblioteca.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function useMediaAsset(path){try{const url=storagePublicUrl(path),t=S.mediaTarget;if(!t){await copyMediaUrl(path);return}if(t==='team-avatar'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({avatar_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Avatar actualizado.','ok');return}if(t==='team-banner'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({banner_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Banner actualizado.','ok');return}if(t==='novel-cover'){if(!S.studioProject?.novels?.id)throw new Error('No hay proyecto activo.');await jreq(`/rest/v1/novels?id=eq.${S.studioProject.novels.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada actualizada.','ok');return}if(t.startsWith('volume-cover:')){const id=t.split(':')[1];await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada del volumen actualizada.','ok');return}if(t.startsWith('block:')){const i=Number(t.split(':')[1]);if(!S.blockEditor?.blocks?.[i])throw new Error('El bloque ya no está disponible.');S.blockEditor.blocks[i].url=url;S.mediaTarget=null;go('studio:project:'+S.studioProject.id);toast('Ilustración seleccionada.','ok');return}}catch(e){toast(friendlyError(e),'bad')}}
async function copyMediaUrl(path){try{const url=storagePublicUrl(path);if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url);else{const ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}toast('URL copiada.','ok')}catch(e){toast('No se pudo copiar la URL.','bad')}}
async function deleteMediaAsset(path){try{if(!path)return;await storageDelete(path);S.mediaFiles=S.mediaFiles.filter(x=>x.path!==path);render();toast('Archivo eliminado de Storage.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function openStudioTeam(id){try{S.studioTeam=await loadStudioTeam(id);await loadTeamMembers(id);go('studio:team:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadStudioTeam(id){const rows=await jreq(`/rest/v1/translator_groups?id=eq.${id}&select=id,slug,name,description,avatar_url,banner_url,primary_color,secondary_color&limit=1`);const g=rows?.[0];if(!g)return null;g.support_links=await jreq(`/rest/v1/support_links?group_id=eq.${id}&select=id,label,url&order=created_at.asc`)||[];return g}
async function refreshStudioTeam(){if(!S.studioTeam?.id)return;S.studioTeam=await loadStudioTeam(S.studioTeam.id);await loadTeamMembers(S.studioTeam.id);await loadStudioData();render()}
async function uploadTeamMedia(e,kind){try{const G=S.studioTeam,file=e.target.files?.[0];if(!G||!file)return;const url=await storageUpload(file,`teams/${G.id}/profile/${storageName(kind,file)}`,false);const input=$(kind==='avatar'?'#teamEditAvatar':'#teamEditBanner');if(input)input.value=url;toast(kind==='avatar'?'Avatar subido.':'Banner subido.','ok')}catch(err){toast(friendlyError(err),'bad')}}
async function saveStudioTeamProfile(){try{const G=S.studioTeam;if(!G)return;const body={name:$('#teamEditName')?.value.trim()||G.name,description:$('#teamEditDescription')?.value.trim()||null,avatar_url:$('#teamEditAvatar')?.value.trim()||null,banner_url:$('#teamEditBanner')?.value.trim()||null,primary_color:$('#teamEditPrimary')?.value.trim()||null,secondary_color:$('#teamEditSecondary')?.value.trim()||null,updated_at:new Date().toISOString()};await jreq(`/rest/v1/translator_groups?id=eq.${G.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await refreshStudioTeam();toast('Perfil del equipo actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addSupportLink(){try{const G=S.studioTeam,label=$('#supportLabel')?.value.trim(),url=$('#supportUrl')?.value.trim();if(!G||!label||!url){toast('Completa etiqueta y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}await jreq('/rest/v1/support_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,label,url:safeUrl(url)})});await refreshStudioTeam();toast('Enlace de apoyo agregado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deleteSupportLink(id){try{await jreq(`/rest/v1/support_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await refreshStudioTeam();toast('Enlace eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addPurchaseLink(){try{const P=S.studioProject,store_name=$('#purchaseStore')?.value.trim(),url=$('#purchaseUrl')?.value.trim();if(!P||!store_name||!url){toast('Completa tienda y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}const volumeRaw=$('#purchaseVolume')?.value;await jreq('/rest/v1/purchase_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({novel_id:P.novels.id,group_id:P.group_id,volume_number:volumeRaw?Number(volumeRaw):null,store_name,region:$('#purchaseRegion')?.value.trim()||null,language_code:$('#purchaseLanguage')?.value.trim()||null,format:$('#purchaseFormat')?.value.trim()||null,url:safeUrl(url),is_verified:false})});await refreshStudioProject();toast('Enlace enviado para verificación.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deletePurchaseLink(id){try{await jreq(`/rest/v1/purchase_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await refreshStudioProject();toast('Enlace eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addDownloadLink(){try{const P=S.studioProject,volume_id=$('#downloadVolume')?.value,format=$('#downloadFormat')?.value.trim(),url=$('#downloadUrl')?.value.trim();if(!P||!volume_id||!format||!url){toast('Completa volumen, formato y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}await jreq('/rest/v1/download_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({volume_id,format,provider:$('#downloadProvider')?.value.trim()||null,url:safeUrl(url)})});await refreshStudioProject();toast('Descarga agregada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deleteDownloadLink(id){try{await jreq(`/rest/v1/download_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await refreshStudioProject();toast('Descarga eliminada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function openStudioProject(id){try{S.studioProject=await loadStudioProject(id);go('studio:project:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadStudioProject(id){const rows=await jreq(`/rest/v1/translations?id=eq.${id}&select=id,title,status,language_code,group_id,novels(id,title,synopsis,cover_url,author_name,genres,tags),translator_groups(id,name),volumes(id,volume_number,title,status,cover_url,sections(id,title,section_type,section_number,status,sort_order,content))&limit=1`);const p=rows?.[0]||null;if(!p)return null;const volumeIds=(p.volumes||[]).map(v=>v.id);const [purchase,downloads]=await Promise.all([jreq(`/rest/v1/purchase_links?novel_id=eq.${p.novels?.id}&group_id=eq.${p.group_id}&select=id,volume_number,store_name,region,language_code,format,url,is_verified&order=created_at.asc`),volumeIds.length?jreq(`/rest/v1/download_links?volume_id=in.(${volumeIds.join(',')})&select=id,volume_id,format,provider,url&order=created_at.asc`):Promise.resolve([])]);p.purchase_links=purchase||[];p.download_links=downloads||[];return p}
async function refreshStudioProject(){if(!S.studioProject?.id)return;S.studioProject=await loadStudioProject(S.studioProject.id);render()}

function splitMetaList(v){return [...new Set(String(v||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,30))]}
async function saveDiscoveryMeta(){try{const P=S.studioProject;if(!P?.novels?.id)return;const genres=splitMetaList($('#projectGenres')?.value),tags=splitMetaList($('#projectTags')?.value);await jreq(`/rest/v1/novels?id=eq.${P.novels.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({genres,tags,updated_at:new Date().toISOString()})});await refreshStudioProject();await loadCatalog();toast('Metadatos de descubrimiento actualizados.','ok')}catch(e){toast(friendlyError(e),'bad')}}
function slugify(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90)||'obra'}
async function createStudioProject(){try{const group_id=$('#newGroup')?.value,title=$('#newNovelTitle')?.value.trim(),title_original=$('#newNovelOriginal')?.value.trim()||null,author_name=$('#newNovelAuthor')?.value.trim()||null,synopsis=$('#newNovelSynopsis')?.value.trim()||null,genres=splitMetaList($('#newNovelGenres')?.value),tags=splitMetaList($('#newNovelTags')?.value),language_code=$('#newTranslationLanguage')?.value.trim()||'es';let cover_url=$('#newNovelCover')?.value.trim()||null;const coverFile=$('#newNovelCoverFile')?.files?.[0];if(!group_id||!title){toast('Completa el equipo y el título.','bad');return}if(coverFile)cover_url=await storageUpload(coverFile,`teams/${group_id}/covers/${storageName('cover',coverFile)}`,false);const novel=await jreq('/rest/v1/novels',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({slug:slugify(title)+'-'+Date.now().toString(36).slice(-5),title,title_original,author_name,synopsis,cover_url,genres,tags,status:'ongoing'})});const n=novel?.[0];if(!n?.id)throw new Error('No se pudo crear la obra.');const tr=await jreq('/rest/v1/translations',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({novel_id:n.id,group_id,language_code,title,status:'active'})});const t=tr?.[0];await loadStudioData();if(t?.id){S.studioProject=await loadStudioProject(t.id);go('studio:project:'+t.id)}else go('studio');toast('Proyecto creado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function createStudioVolume(){try{const P=S.studioProject;if(!P)return;const volume_number=Number($('#projectVolumeNumber')?.value||1),title=$('#projectVolumeTitle')?.value.trim()||null;await jreq('/rest/v1/volumes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({translation_id:P.id,volume_number,title,status:'draft'})});await refreshStudioProject();toast('Volumen creado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function uploadVolumeCover(volumeId,file){try{const P=S.studioProject;if(!P||!file)return;const url=await storageUpload(file,`teams/${P.group_id}/volumes/${volumeId}/${storageName('cover',file)}`,false);await jreq(`/rest/v1/volumes?id=eq.${volumeId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});await refreshStudioProject();toast('Portada del volumen actualizada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function uploadBlockImage(index,file){try{syncEditorInputs();const P=S.studioProject,sec=S.studioProject?.editingSection;if(!P||!sec||!file||!S.blockEditor?.blocks[index])return;const url=await storageUpload(file,`teams/${P.group_id}/illustrations/${sec.id}/${storageName('illustration',file)}`,false);S.blockEditor.blocks[index].url=url;render();toast('Ilustración subida.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function createStudioSection(volumeId){try{const count=(S.studioProject?.volumes?.find(v=>v.id===volumeId)?.sections||[]).length;const rows=await jreq('/rest/v1/sections',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({volume_id:volumeId,section_type:'chapter',section_number:count+1,title:`Capítulo ${count+1}`,content:[{type:'paragraph',text:''}],sort_order:count+1,status:'draft'})});await refreshStudioProject();const sec=rows?.[0];if(sec){S.studioProject.editingSection=sec;render()}toast('Capítulo creado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
function editStudioSection(id){const sec=S.studioProject?.volumes?.flatMap(v=>v.sections||[]).find(s=>s.id===id);if(sec){S.studioProject.editingSection=JSON.parse(JSON.stringify(sec));S.blockEditor={sectionId:sec.id,blocks:(Array.isArray(sec.content)?sec.content:[]).map(normalizeBlock)};render();setTimeout(()=>$('#editSectionTitle')?.focus(),0)}}
async function saveStudioSection(){try{const sec=S.studioProject?.editingSection;if(!sec)return;const title=$('#editSectionTitle')?.value.trim()||'Sin título',section_type=$('#editSectionType')?.value||'chapter';syncEditorInputs();const content=(S.blockEditor?.blocks||[]).map(normalizeBlock).filter(b=>b.type==='separator'||(b.type==='image'&&b.url)||(b.type==='ruby'&&(b.base||b.reading))||String(b.text||'').trim());if(S.studioProject?.editorial_mode&&$('#createRevisionOnSave')?.checked){await jreq('/rest/v1/section_revisions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({section_id:sec.id,created_by:S.user.id,title:sec.title,section_type:sec.section_type,content:sec.content||[],revision_note:$('#revisionNote')?.value.trim()||null})})}await jreq(`/rest/v1/sections?id=eq.${sec.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({title,section_type,content,updated_at:new Date().toISOString()})});S.blockEditor=null;S.revisionPreview=null;await refreshStudioProject();toast('Cambios guardados.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function moveStudioSection(id,dir){try{const P=S.studioProject;if(!P)return;for(const v of P.volumes||[]){const arr=(v.sections||[]).slice().sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));const i=arr.findIndex(x=>x.id===id);if(i<0)continue;const j=i+dir;if(j<0||j>=arr.length)return;const a=arr[i],b=arr[j],ao=a.sort_order??i+1,bo=b.sort_order??j+1;await Promise.all([jreq(`/rest/v1/sections?id=eq.${a.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({sort_order:bo})}),jreq(`/rest/v1/sections?id=eq.${b.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({sort_order:ao})})]);await refreshStudioProject();toast('Orden actualizado.','ok');return}}catch(e){toast(friendlyError(e),'bad')}}

async function setEditorialMode(enabled){try{const P=S.studioProject;if(!P)return;await jreq(`/rest/v1/translations?id=eq.${P.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({editorial_mode:!!enabled,updated_at:new Date().toISOString()})});S.revisionHistory=[];S.revisionPreview=null;await refreshStudioProject();toast(enabled?'Flujo editorial activado.':'Flujo editorial desactivado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function loadRevisionHistory(sectionId){try{const sec=S.studioProject?.volumes?.flatMap(v=>v.sections||[]).find(x=>x.id===sectionId);if(!sec)return;S.studioProject.editingSection=JSON.parse(JSON.stringify(sec));S.blockEditor={sectionId:sec.id,blocks:(sec.content||[]).map(normalizeBlock)};S.revisionHistory=await jreq(`/rest/v1/section_revisions?section_id=eq.${sectionId}&select=id,title,section_type,content,revision_note,created_at,profiles(id,username,display_name)&order=created_at.desc&limit=50`)||[];S.revisionPreview=null;render()}catch(e){toast(friendlyError(e),'bad')}}
function previewEditingSection(){syncEditorInputs();S.revisionPreview={mode:'preview',title:$('#editSectionTitle')?.value||S.studioProject?.editingSection?.title||'',content:(S.blockEditor?.blocks||[]).map(normalizeBlock)};render()}
function previewStoredSection(id){const sec=S.studioProject?.volumes?.flatMap(v=>v.sections||[]).find(x=>x.id===id);if(!sec)return;S.studioProject.editingSection=JSON.parse(JSON.stringify(sec));S.blockEditor={sectionId:sec.id,blocks:(sec.content||[]).map(normalizeBlock)};S.revisionPreview={mode:'preview',title:sec.title,content:sec.content||[]};render()}
function compareRevision(id){const r=S.revisionHistory.find(x=>x.id===id),sec=S.studioProject?.editingSection;if(!r||!sec)return;syncEditorInputs();S.revisionPreview={mode:'compare',old:r.content||[],current:(S.blockEditor?.blocks||sec.content||[]).map(normalizeBlock)};render()}
async function restoreRevision(id){try{const r=S.revisionHistory.find(x=>x.id===id),sec=S.studioProject?.editingSection;if(!r||!sec)return;await jreq('/rest/v1/section_revisions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({section_id:sec.id,created_by:S.user.id,title:sec.title,section_type:sec.section_type,content:sec.content||[],revision_note:'Copia automática antes de restaurar una revisión'})});await jreq(`/rest/v1/sections?id=eq.${sec.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({title:r.title,section_type:r.section_type,content:r.content,updated_at:new Date().toISOString()})});S.revisionPreview=null;await refreshStudioProject();toast('Revisión restaurada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function setStudioSectionStatus(id,status){try{await jreq(`/rest/v1/sections?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,published_at:status==='published'?new Date().toISOString():null,updated_at:new Date().toISOString()})});await refreshStudioProject();await loadCatalog();toast(status==='published'?'Capítulo publicado.':'Capítulo ocultado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function setStudioVolumeStatus(id,status){try{await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,published_at:status==='published'?new Date().toISOString():null,updated_at:new Date().toISOString()})});await refreshStudioProject();await loadCatalog();toast(status==='published'?'Volumen publicado.':'Volumen ocultado.','ok')}catch(e){toast(friendlyError(e),'bad')}}

function currentReaderPercent(includeCurrentAsRead=false){
 const R=S.readerSection;if(!R)return 0;
 const nav=R.navigation||[],idx=nav.findIndex(x=>x.id===R.id);
 if(idx<0||!nav.length)return includeCurrentAsRead?100:5;
 const fraction=(idx+(includeCurrentAsRead?1:.05))/nav.length;
 return Math.max(1,Math.min(100,Math.round(fraction*1000)/10))
}
function nonRegressingPercent(candidate){
 const current=S.readingProgress.find(x=>x.translation_id===S.readerSection?.translation_id);
 return Math.max(Number(current?.progress_percent||0),Number(candidate||0))
}
async function markCurrentSectionRead(){await saveReaderProgress(nonRegressingPercent(currentReaderPercent(true)),true)}
function chapterCacheKey(id){return `nlobi_chapter_${id}`}
function cacheReaderChapter(r){try{localStorage.setItem(chapterCacheKey(r.id),JSON.stringify({...r,cached_at:new Date().toISOString()}));const idx=JSON.parse(localStorage.getItem('nlobi_cached_chapters')||'[]').filter(x=>x.id!==r.id);idx.unshift({id:r.id,title:r.title||'Capítulo',novel_title:r.novel_title||'',cached_at:new Date().toISOString()});localStorage.setItem('nlobi_cached_chapters',JSON.stringify(idx.slice(0,30)))}catch(e){console.warn('No se pudo guardar capítulo offline',e)}}
function readCachedChapter(id){try{return JSON.parse(localStorage.getItem(chapterCacheKey(id))||'null')}catch{return null}}
function queueProgress(payload){try{const q=JSON.parse(localStorage.getItem('nlobi_progress_queue')||'[]');const filtered=q.filter(x=>!(x.user_id===payload.user_id&&x.translation_id===payload.translation_id));filtered.push(payload);localStorage.setItem('nlobi_progress_queue',JSON.stringify(filtered))}catch(e){console.warn(e)}}
async function flushProgressQueue(){if(!navigator.onLine||!S.token)return;let q=[];try{q=JSON.parse(localStorage.getItem('nlobi_progress_queue')||'[]')}catch{}if(!q.length)return;const left=[];for(const p of q){try{await jreq('/rest/v1/reading_progress?on_conflict=user_id,translation_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(p.progress)});await jreq('/rest/v1/library_entries?on_conflict=user_id,translation_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(p.library)})}catch(e){left.push(p)}}localStorage.setItem('nlobi_progress_queue',JSON.stringify(left));if(q.length&&!left.length)toast('Progreso offline sincronizado.','ok')}
async function openReader(sectionId,translationId){try{if(!navigator.onLine){const cached=readCachedChapter(sectionId);if(!cached)throw new Error('Este capítulo no está disponible sin conexión todavía. Ábrelo una vez con internet para guardarlo.');S.readerSection=cached;S.readerComments=[];if(S.user)await saveReaderProgress(nonRegressingPercent(currentReaderPercent(false)),false);go('reader:'+sectionId);return}const secRows=await jreq(`/rest/v1/sections?id=eq.${sectionId}&status=eq.published&select=id,volume_id,title,section_type,section_number,content&limit=1`);const sec=secRows?.[0];if(!sec)throw new Error('El capítulo no está disponible.');const volRows=await jreq(`/rest/v1/volumes?id=eq.${sec.volume_id}&select=id,translation_id,volume_number,title&limit=1`);const vol=volRows?.[0];const trId=translationId||vol?.translation_id;const tr=await loadTranslationDetail(trId);const navigation=(tr?.volumes||[]).filter(v=>v.status==='published').sort((a,b)=>Number(a.volume_number)-Number(b.volume_number)).flatMap(v=>(v.sections||[]).filter(x=>x.status==='published').sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(x=>({...x,volume_id:v.id,volume_number:v.volume_number})));S.readerSection={...sec,translation_id:trId,volume_number:vol?.volume_number,novel_title:tr?.novels?.title,navigation};cacheReaderChapter(S.readerSection);await loadReaderComments(sectionId);if(S.user){await recordReadingHistory(sectionId,trId);await saveReaderProgress(nonRegressingPercent(currentReaderPercent(false)),false);}go('reader:'+sectionId)}catch(e){const cached=readCachedChapter(sectionId);if(cached){S.readerSection=cached;S.readerComments=[];go('reader:'+sectionId);toast('Mostrando la copia guardada sin conexión.','ok')}else toast(friendlyError(e),'bad')}}
async function saveReaderProgress(percent=100,announce=true){try{if(!S.user||!S.readerSection)return;const R=S.readerSection,progress={user_id:S.user.id,translation_id:R.translation_id,volume_id:R.volume_id,section_id:R.id,progress_percent:percent,anchor:percent>=100?'end':'b:0',updated_at:new Date().toISOString()},currentLib=S.library.find(x=>x.translation_id===R.translation_id),library={user_id:S.user.id,translation_id:R.translation_id,status:['completed','paused','dropped'].includes(currentLib?.status)?currentLib.status:'reading',is_favorite:!!currentLib?.is_favorite};if(!navigator.onLine){queueProgress({user_id:S.user.id,translation_id:R.translation_id,progress,library});if(announce)toast('Progreso guardado en este dispositivo. Se sincronizará al volver la conexión.','ok');return}await jreq('/rest/v1/reading_progress?on_conflict=user_id,translation_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(progress)});await jreq('/rest/v1/library_entries?on_conflict=user_id,translation_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(library)});await loadUser();if(announce)toast(percent>=100?'Lectura marcada como completada.':'Progreso guardado.','ok')}catch(e){const R=S.readerSection;if(S.user&&R){queueProgress({user_id:S.user.id,translation_id:R.translation_id,progress:{user_id:S.user.id,translation_id:R.translation_id,volume_id:R.volume_id,section_id:R.id,progress_percent:percent,anchor:percent>=100?'end':'b:0',updated_at:new Date().toISOString()},library:{user_id:S.user.id,translation_id:R.translation_id,status:['completed','paused','dropped'].includes(S.library.find(x=>x.translation_id===R.translation_id)?.status)?S.library.find(x=>x.translation_id===R.translation_id).status:'reading',is_favorite:!!S.library.find(x=>x.translation_id===R.translation_id)?.is_favorite}});if(announce)toast('No se pudo sincronizar; el progreso quedó guardado localmente.','ok')}else if(announce)toast(friendlyError(e),'bad')}}
async function login(){try{const email=$('#email').value.trim(),password=$('#pass').value;const d=await jreq('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});S.token=d.access_token||'';localStorage.setItem('nlobi_token',S.token);await loadUser();go('home',true)}catch(e){toast(friendlyError(e),'bad')}}
async function signup(){try{const email=$('#email').value.trim(),password=$('#pass').value,name=$('#name').value.trim(),account_type=document.querySelector('input[name=atype]:checked').value;await jreq('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password,data:{display_name:name,account_type}})});toast('Cuenta creada. Revisa tu correo si se requiere confirmación.','ok');S.authMode='login';render()}catch(e){toast(friendlyError(e),'bad')}}
function logout(){S.token='';localStorage.removeItem('nlobi_token');S.user=S.profile=null;S.groups=[];S.library=[];S.readingProgress=[];S.readingHistory=[];S.notes=[];S.admin=false;S.view='home';render()}
async function loadCatalog(){S.catalog=await jreq('/rest/v1/translations?select=id,title,status,language_code,popularity_score,updated_at,novels(id,title,synopsis,cover_url,author_name,genres,tags),translator_groups(id,name)&status=in.(active,complete,paused)&order=updated_at.desc')||[]}
async function loadUser(){if(!S.token)return;try{S.user=await jreq('/auth/v1/user');const uid=S.user.id;const [p,g,l,rp,rh,a,n,np,me]=await Promise.all([
 jreq(`/rest/v1/profiles?id=eq.${uid}&select=id,username,display_name,avatar_url,bio,account_type,public_library,public_activity`),
 jreq(`/rest/v1/group_members?user_id=eq.${uid}&select=role,translator_groups(id,name,slug)`),
 jreq(`/rest/v1/library_entries?user_id=eq.${uid}&select=translation_id,status,is_favorite,updated_at,translations(id,title,novels(id,title,cover_url),translator_groups(id,name))&order=updated_at.desc`),
 jreq(`/rest/v1/reading_progress?user_id=eq.${uid}&select=translation_id,volume_id,section_id,progress_percent,anchor,updated_at,volumes(id,volume_number,title),sections(id,title,section_number)&order=updated_at.desc`),
 jreq(`/rest/v1/reading_history?user_id=eq.${uid}&select=section_id,translation_id,viewed_at,sections(id,title,section_number,volumes(id,volume_number,translations(id,title,novels(id,title))))&order=viewed_at.desc&limit=50`),
 jreq(`/rest/v1/team_applications?select=id,applicant_id,requested_name,requested_slug,description,website_url,status,created_at&order=created_at.desc`),
 jreq(`/rest/v1/notifications?user_id=eq.${uid}&select=id,notification_type,title,body,translation_id,section_id,actor_user_id,read_at,created_at&order=created_at.desc&limit=100`),
 jreq(`/rest/v1/notification_preferences?user_id=eq.${uid}&select=user_id,new_publications,comment_replies,team_updates,system_updates&limit=1`),
 jreq(`/rest/v1/site_admins?user_id=eq.${uid}&select=user_id`)
 ]);S.profile=p?.[0]||null;S.groups=g||[];S.library=l||[];S.readingProgress=rp||[];S.readingHistory=rh||[];S.apps=a||[];S.notes=n||[];S.notificationPrefs=np?.[0]||{new_publications:true,comment_replies:true,team_updates:true,system_updates:true};S.admin=!!me?.length;await loadStudioData();await loadBetaFeedback();await loadFollows();if(S.admin)await loadAdminData()}catch(e){logout();throw e}}
async function loadAdminData(){const [u,t,r,c,v,se,p,b,a]=await Promise.all([
 jreq('/rest/v1/profiles?select=id,username,display_name,account_type,created_at&order=created_at.desc&limit=200'),
 jreq('/rest/v1/translator_groups?select=id,name,slug,description,created_at&order=created_at.desc&limit=200'),
 jreq('/rest/v1/comment_reports?select=id,comment_id,reason,status,created_at,comments(id,body,user_id,section_id)&order=created_at.desc&limit=200'),
 jreq('/rest/v1/translations?select=id,title,status,updated_at,novels(id,title),translator_groups(id,name)&order=updated_at.desc&limit=200'),
 jreq('/rest/v1/volumes?select=id,volume_number,title,status,updated_at,translations(id,title,novels(id,title))&order=updated_at.desc&limit=200'),
 jreq('/rest/v1/sections?select=id,title,status,updated_at,volumes(id,translations(id,title,novels(id,title)))&order=updated_at.desc&limit=300'),
 jreq('/rest/v1/purchase_links?select=id,volume_number,store_name,url,is_verified,created_at,novels(id,title),translator_groups(id,name)&order=created_at.desc&limit=200'),
 jreq('/rest/v1/beta_feedback?select=id,user_id,category,title,description,page,status,admin_note,created_at,profiles(id,username,display_name)&order=created_at.desc&limit=200'),
 jreq('/rest/v1/moderation_audit?select=id,action_type,target_type,target_id,details,created_at&order=created_at.desc&limit=300')
]);S.adminUsers=u||[];S.adminTeams=t||[];S.adminReports=r||[];S.adminContent=c||[];S.adminVolumes=v||[];S.adminSections=se||[];S.adminPurchaseLinks=p||[];S.adminBetaFeedback=b||[];S.adminAudit=a||[]}

async function loadBetaFeedback(){if(!S.user){S.betaFeedback=[];return}S.betaFeedback=await jreq(`/rest/v1/beta_feedback?user_id=eq.${S.user.id}&select=id,category,title,description,status,admin_note,created_at&order=created_at.desc&limit=50`)||[]}
async function runBetaChecks(){const tests=[];const run=async(label,fn)=>{try{const detail=await fn();tests.push({label,ok:true,detail:detail||'Correcto'})}catch(e){tests.push({label,ok:false,detail:friendlyError(e)})}};await run('Frontend',async()=>`Vista ${S.view} renderizada`);await run('Supabase Data API',async()=>{await jreq('/rest/v1/translations?select=id&limit=1');return'Consulta pública correcta'});await run('Sesión Auth',async()=>{const u=await jreq('/auth/v1/user');return u?.id?'Sesión válida':'Sin sesión válida'});await run('Perfil',async()=>{const p=await jreq(`/rest/v1/profiles?id=eq.${S.user.id}&select=id&limit=1`);return p?.length?'Perfil accesible':'Perfil no encontrado'});await run('Biblioteca',async()=>{await jreq(`/rest/v1/library_entries?user_id=eq.${S.user.id}&select=translation_id&limit=1`);return'RLS de biblioteca correcto'});await run('Studio / equipos',async()=>{await jreq(`/rest/v1/group_members?user_id=eq.${S.user.id}&select=group_id&limit=1`);return'Permisos de equipo consultables'});S.betaChecks=tests;render();toast(tests.every(x=>x.ok)?'Diagnóstico completado sin fallos.':'Diagnóstico completado con incidencias.',tests.every(x=>x.ok)?'ok':'bad')}
async function submitBetaFeedback(){try{const category=$('#betaCategory')?.value||'bug',title=$('#betaTitle')?.value.trim()||'',description=$('#betaDescription')?.value.trim()||'';if(title.length<3||description.length<3){toast('Añade un título y una descripción más completos.','bad');return}await jreq('/rest/v1/beta_feedback',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:S.user.id,category,title,description,page:location.hash||'#home',browser_info:navigator.userAgent.slice(0,500)})});await loadBetaFeedback();render();toast('Reporte Beta enviado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function updateBetaFeedbackStatus(id,status){try{await jreq(`/rest/v1/beta_feedback?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,updated_at:new Date().toISOString()})});await audit(status==='reviewing'?'feedback_reviewing':status==='resolved'?'feedback_resolved':'feedback_dismissed','beta_feedback',id,{status});await loadAdminData();render();toast('Estado actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function audit(action_type,target_type,target_id,details={}){if(!S.admin||!S.user)return;await jreq('/rest/v1/moderation_audit',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({actor_user_id:S.user.id,action_type,target_type,target_id,details})})}
async function reviewReport(id,status){try{await jreq(`/rest/v1/comment_reports?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status})});await audit(status==='reviewed'?'report_reviewed':'report_dismissed','comment_report',id);await loadAdminData();render()}catch(e){toast(friendlyError(e),'bad')}}
async function deleteReportedComment(commentId,reportId){try{await jreq(`/rest/v1/comments?id=eq.${commentId}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await audit('comment_deleted','comment',commentId,{report_id:reportId||null});if(reportId)await jreq(`/rest/v1/comment_reports?id=eq.${reportId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'reviewed'})});await loadAdminData();render()}catch(e){toast(friendlyError(e),'bad')}}
async function setTranslationStatus(id,status){try{await jreq(`/rest/v1/translations?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,updated_at:new Date().toISOString()})});await audit(status==='withdrawn'?'translation_hidden':'translation_restored','translation',id,{status});await loadCatalog();await loadAdminData();render()}catch(e){toast(friendlyError(e),'bad')}}

async function recordReadingHistory(sectionId,translationId){try{if(!S.user||!navigator.onLine)return;await jreq('/rest/v1/reading_history?on_conflict=user_id,section_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:S.user.id,section_id:sectionId,translation_id:translationId,viewed_at:new Date().toISOString()})})}catch(e){console.warn('Historial',e)}}
async function setLibraryStatus(id,status){try{await jreq(`/rest/v1/library_entries?user_id=eq.${S.user.id}&translation_id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,updated_at:new Date().toISOString()})});const x=S.library.find(v=>v.translation_id===id);if(x)x.status=status;render();toast('Estado actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function toggleLibraryFavorite(id){try{const x=S.library.find(v=>v.translation_id===id);if(!x)return;const val=!x.is_favorite;await jreq(`/rest/v1/library_entries?user_id=eq.${S.user.id}&translation_id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({is_favorite:val,updated_at:new Date().toISOString()})});x.is_favorite=val;render()}catch(e){toast(friendlyError(e),'bad')}}
async function removeLibraryEntry(id){try{await jreq(`/rest/v1/library_entries?user_id=eq.${S.user.id}&translation_id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});S.library=S.library.filter(x=>x.translation_id!==id);render();toast('Lectura eliminada de tu biblioteca.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function clearReadingHistory(){try{await jreq(`/rest/v1/reading_history?user_id=eq.${S.user.id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});S.readingHistory=[];render();toast('Historial eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
function removeOfflineChapter(id){try{localStorage.removeItem(chapterCacheKey(id));const idx=cachedChapterIndex().filter(x=>x.id!==id);localStorage.setItem('nlobi_cached_chapters',JSON.stringify(idx));render()}catch(e){toast('No se pudo eliminar la copia offline.','bad')}}
function clearOfflineLibrary(){try{for(const x of cachedChapterIndex())localStorage.removeItem(chapterCacheKey(x.id));localStorage.removeItem('nlobi_cached_chapters');render();toast('Copias offline eliminadas.','ok')}catch(e){toast('No se pudieron eliminar las copias offline.','bad')}}
async function openOfflineChapter(id){const cached=readCachedChapter(id);if(!cached){removeOfflineChapter(id);toast('La copia offline ya no está disponible.','bad');return}S.readerSection=cached;S.readerComments=[];go('reader:'+id)}
async function addLibrary(id){try{if(!S.user)return;const existing=S.library.find(x=>x.translation_id===id);if(existing){toast('Esta obra ya está en tu biblioteca.','ok');return}await jreq('/rest/v1/library_entries?on_conflict=user_id,translation_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:S.user.id,translation_id:id,status:'plan_to_read',is_favorite:false})});await loadUser();render();toast('Añadida a tu biblioteca.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function sendApplication(){try{const name=$('#teamName').value.trim();if(!name)return;await jreq('/rest/v1/team_applications',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({applicant_id:S.user.id,requested_name:name,requested_slug:name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+Date.now().toString(36).slice(-4),description:$('#teamDesc').value.trim()||null,website_url:$('#teamWeb').value.trim()||null,status:'pending'})});await loadUser();S.view='auth';render()}catch(e){toast(friendlyError(e),'bad')}}
async function readNote(id){try{await jreq(`/rest/v1/notifications?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({read_at:new Date().toISOString()})});const n=S.notes.find(x=>x.id===id);if(n)n.read_at=new Date().toISOString();render()}catch(e){toast(friendlyError(e),'bad')}}
async function markAllNotificationsRead(){try{if(!S.user)return;await jreq(`/rest/v1/notifications?user_id=eq.${S.user.id}&read_at=is.null`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({read_at:new Date().toISOString()})});S.notes.forEach(n=>{if(!n.read_at)n.read_at=new Date().toISOString()});render();toast('Todas las notificaciones se marcaron como leídas.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deleteNotification(id){try{await jreq(`/rest/v1/notifications?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});S.notes=S.notes.filter(n=>n.id!==id);render()}catch(e){toast(friendlyError(e),'bad')}}
async function clearReadNotifications(){try{if(!S.user)return;await jreq(`/rest/v1/notifications?user_id=eq.${S.user.id}&read_at=not.is.null`,{method:'DELETE',headers:{Prefer:'return=minimal'}});S.notes=S.notes.filter(n=>!n.read_at);render();toast('Notificaciones leídas eliminadas.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function saveNotificationPreference(key,value){try{if(!S.user)return;const next={...S.notificationPrefs,[key]:!!value};await jreq('/rest/v1/notification_preferences?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:S.user.id,...next,updated_at:new Date().toISOString()})});S.notificationPrefs=next;render();toast('Preferencias actualizadas.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function openNotificationSection(id,translationId){const n=S.notes.find(x=>x.section_id===id&&!x.read_at);if(n)await readNote(n.id);await openReader(id,translationId)}
async function reviewApp(id,ok){try{if(!S.admin)return;const note=$(`[data-app-note="${id}"]`)?.value.trim()||null;await jreq('/rest/v1/rpc/admin_review_team_application',{method:'POST',body:JSON.stringify({application_id:id,decision:ok?'approved':'rejected',note})});await loadUser();await loadAdminData();render();toast(ok?'Solicitud aprobada y equipo creado.':'Solicitud rechazada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function reviewPurchaseLink(id,verified){try{await jreq('/rest/v1/rpc/admin_review_purchase_link',{method:'POST',body:JSON.stringify({link_id:id,verified})});await loadAdminData();render();toast(verified?'Enlace oficial verificado.':'Verificación retirada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deleteAdminPurchaseLink(id){try{await jreq(`/rest/v1/purchase_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await audit('link_deleted','purchase_link',id);await loadAdminData();render();toast('Enlace eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function setAdminVolumeStatus(id,status){try{await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,updated_at:new Date().toISOString()})});await audit(status==='hidden'?'volume_hidden':'volume_restored','volume',id,{status});await loadAdminData();render();toast('Volumen actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function setAdminSectionStatus(id,status){try{await jreq(`/rest/v1/sections?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,updated_at:new Date().toISOString()})});await audit(status==='hidden'?'section_hidden':'section_restored','section',id,{status});await loadAdminData();render();toast('Sección actualizada.','ok')}catch(e){toast(friendlyError(e),'bad')}}

let deferredInstallPrompt=null;
async function installPwa(){if(!deferredInstallPrompt){toast('La instalación no está disponible todavía en este navegador.','bad');return}deferredInstallPrompt.prompt();try{await deferredInstallPrompt.userChoice}catch{}deferredInstallPrompt=null;S.pwaInstallReady=false;render()}
function restoreReaderRouteFromCache(){if(!S.view.startsWith('reader:')||S.readerSection)return;const id=S.view.split(':')[1],cached=readCachedChapter(id);if(cached){S.readerSection=cached;S.readerComments=[]}}
function registerPwa(){if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(e=>console.warn('SW',e))}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;S.pwaInstallReady=true;render()});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;S.pwaInstallReady=false;toast('NLOBI quedó instalada.','ok');render()});
async function boot(isRetry=false){if(localStorage.getItem('nlobi_dark')==='1')document.body.classList.add('dark');S.view=routeFromHash();restoreReaderRouteFromCache();setNetworkBadge();render();try{if(navigator.onLine){await loadCatalog();S.err='';if(S.token){await loadUser();await flushProgressQueue()}if(isRetry)toast('Conexión restablecida.','ok')}else{S.err=''}}catch(e){S.err=friendlyError(e,'No se pudo cargar la información en este momento.');console.error(e)}render()}
window.addEventListener('hashchange',()=>{S.view=routeFromHash();render();window.scrollTo({top:0,behavior:'smooth'})});
window.addEventListener('online',async()=>{S.online=true;setNetworkBadge();toast('Conexión restablecida.','ok');await flushProgressQueue();boot(true)});
window.addEventListener('offline',()=>{S.online=false;setNetworkBadge();render();toast('Sin conexión. Los capítulos guardados siguen disponibles.','bad')});
window.addEventListener('error',e=>{console.error('[NLOBI global error]',e.error||e.message,e.filename||'',e.lineno||'',e.colno||'')});
window.addEventListener('unhandledrejection',e=>{console.error('[NLOBI unhandled rejection]',e.reason)});
if(!location.hash)history.replaceState(null,'','#home');
registerPwa();
boot();